  (1900000000000000407, '虾仁炒饭', '虾仁炒饭', NULL, 1, NULL, 1, 4, '鲜香', '米饭做主角的快手主食，一碗就能解决一顿饭。', 2, 12, 12, 0, '[{"no": 1, "text": "米饭备好，虾仁切小丁。"}, {"no": 2, "text": "锅烧热倒油，先把配料炒香。"}, {"no": 3, "text": "加入虾仁翻炒均匀。"}, {"no": 4, "text": "倒入米饭，用铲子压散翻炒。"}, {"no": 5, "text": "加盐和生抽调味，大火翻炒到入味出锅。"}]', '["盐", "生抽", "黑胡椒"]', '["炒锅", "煮锅"]', '["米饭用隔夜的，水分少更好炒散。", "面条煮到八分熟就捞，后面还要炒。"]', '["米饭可以用同季的替代品，用量保持不变。"]', 423.9, 18.2, 4.7, 75.2, 2.8, 72.2, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-08-31 11:23:45', 0, '2026-08-31 11:23:45', '2026-08-31 11:23:45'),
  (1900000000000000415, '韭菜鸡蛋饺子', '韭菜鸡蛋饺子', NULL, 1, NULL, 1, 2, '家常', '饺子皮做主角的快手主食，一碗就能解决一顿饭。', 2, 25, 15, 0, '[{"no": 1, "text": "饺子皮备好，韭菜切小丁。"}, {"no": 2, "text": "锅烧热倒油，先把配料炒香。"}, {"no": 3, "text": "加入韭菜翻炒均匀。"}, {"no": 4, "text": "倒入饺子皮，用铲子压散翻炒。"}, {"no": 5, "text": "加盐和生抽调味，大火翻炒到入味出锅。"}]', '["盐", "生抽", "芝麻油"]', '["炒锅", "煮锅"]', '["米饭用隔夜的，水分少更好炒散。", "面条煮到八分熟就捞，后面还要炒。"]', '["饺子皮可以用同季的替代品，用量保持不变。"]', 658.8, 23.8, 9.3, 118.4, 6.2, 115.0, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-04-09 19:29:56', 0, '2026-04-09 19:29:56', '2026-04-09 19:29:56'),
  (1900000000000000422, '猪肉白菜饺子', '猪肉白菜饺子', NULL, 1, NULL, 1, 4, '家常', '饺子皮做主角的快手主食，一碗就能解决一顿饭。', 2, 25, 15, 0, '[{"no": 1, "text": "饺子皮备好，猪肉切小丁。"}, {"no": 2, "text": "锅烧热倒油，先把配料炒香。"}, {"no": 3, "text": "加入猪肉翻炒均匀。"}, {"no": 4, "text": "倒入饺子皮，用铲子压散翻炒。"}, {"no": 5, "text": "加盐和生抽调味，大火翻炒到入味出锅。"}]', '["盐", "生抽", "芝麻油", "料酒"]', '["炒锅", "煮锅"]', '["米饭用隔夜的，水分少更好炒散。", "面条煮到八分熟就捞，后面还要炒。"]', '["饺子皮可以用同季的替代品，用量保持不变。"]', 396.8, 19.3, 9.2, 58.3, 2.9, 45.2, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-09-05 14:39:01', 0, '2026-09-05 14:39:01', '2026-09-05 14:39:01'),
  (1900000000000000430, '香煎带鱼', '香煎带鱼', NULL, 1, NULL, 1, 2, '外酥里嫩', '带鱼煎到两面金黄，外酥里嫩，配饭配酒都合适。', 2, 15, 15, 0, '[{"no": 1, "text": "带鱼洗净擦干水分，用料酒腌 15 分钟。"}, {"no": 2, "text": "平底锅倒油烧至六成热。"}, {"no": 3, "text": "放入带鱼，中小火煎到一面定型。"}, {"no": 4, "text": "翻面继续煎 5 分钟，煎至两面金黄。"}, {"no": 5, "text": "出锅吸掉多余油，撒上生姜即可。"}]', '["盐", "料酒", "生抽", "黑胡椒"]', '["平底锅"]', '["食材表面擦干再下锅，不容易溅油。", "一面定型再翻，别急着动它。"]', '["带鱼可以用同季的替代品，用量保持不变。"]', 238.2, 40.6, 6.8, 1.5, 0.1, 203.1, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-05-18 20:12:56', 0, '2026-05-18 20:12:56', '2026-05-18 20:12:56'),
  (1900000000000000437, '香煎三文鱼', '香煎三文鱼', NULL, 1, NULL, 1, 2, '鲜嫩', '三文鱼煎到两面金黄，外酥里嫩，配饭配酒都合适。', 1, 10, 10, 0, '[{"no": 1, "text": "三文鱼洗净擦干水分，用黑胡椒腌 15 分钟。"}, {"no": 2, "text": "平底锅倒油烧至六成热。"}, {"no": 3, "text": "放入三文鱼，中小火煎到一面定型。"}, {"no": 4, "text": "翻面继续煎 3 分钟，煎至两面金黄。"}, {"no": 5, "text": "出锅吸掉多余油，撒上葱花即可。"}]', '["盐", "黑胡椒", "柠檬", "蜂蜜"]', '["平底锅"]', '["食材表面擦干再下锅，不容易溅油。", "一面定型再翻，别急着动它。"]', '["三文鱼可以用同季的替代品，用量保持不变。"]', 157.5, 27.0, 4.5, 0.8, 0.0, 135.0, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-04-15 17:50:31', 0, '2026-04-15 17:50:31', '2026-04-15 17:50:31'),
  (1900000000000000443, '葱油饼', '葱油饼', NULL, 1, NULL, 1, 4, '酥脆', '面粉煎到两面金黄，外酥里嫩，配饭配酒都合适。', 2, 30, 20, 0, '[{"no": 1, "text": "面粉洗净擦干水分，用芝麻油腌 15 分钟。"}, {"no": 2, "text": "平底锅倒油烧至六成热。"}, {"no": 3, "text": "放入面粉，中小火煎到一面定型。"}, {"no": 4, "text": "翻面继续煎 6 分钟，煎至两面金黄。"}, {"no": 5, "text": "出锅吸掉多余油，撒上葱即可。"}]', '["盐", "芝麻油"]', '["平底锅"]', '["食材表面擦干再下锅，不容易溅油。", "一面定型再翻，别急着动它。"]', '["面粉可以用同季的替代品，用量保持不变。"]', 263.9, 6.3, 1.0, 56.5, 2.3, 5.3, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-06-11 00:45:22', 0, '2026-06-11 00:45:22', '2026-06-11 00:45:22'),
  (1900000000000000448, '凉拌黄瓜', '凉拌黄瓜', NULL, 1, NULL, 1, 3, '爽脆', '凉拌黄瓜爽脆开胃，不用开火也能端上桌。', 1, 8, 5, 1, '[{"no": 1, "text": "黄瓜洗净，按纹理切好。"}, {"no": 2, "text": "锅中水烧开，黄瓜焯 30 秒立刻捞出。"}, {"no": 3, "text": "过一遍凉开水，沥干后装盘。"}, {"no": 4, "text": "醋和生抽调成料汁。"}, {"no": 5, "text": "淋上料汁拌匀，静置 5 分钟入味即可。"}]', '["醋", "生抽", "芝麻油", "盐"]', '["拌盆"]', '["焯水后过一遍凉开水，口感更脆。", "料汁吃之前再淋，放久了会出水。"]', '["黄瓜可以用同季的替代品，用量保持不变。"]', 27.3, 1.7, 0.3, 5.2, 2.1, 8.4, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-04-16 14:54:00', 0, '2026-04-16 14:54:00', '2026-04-16 14:54:00'),
  (1900000000000000455, '拍黄瓜', '拍黄瓜', NULL, 1, NULL, 1, 4, '爽口', '拍黄瓜爽脆开胃，不用开火也能端上桌。', 1, 6, 5, 1, '[{"no": 1, "text": "黄瓜洗净，按纹理切好。"}, {"no": 2, "text": "锅中水烧开，黄瓜焯 30 秒立刻捞出。"}, {"no": 3, "text": "过一遍凉开水，沥干后装盘。"}, {"no": 4, "text": "醋和生抽调成料汁。"}, {"no": 5, "text": "淋上料汁拌匀，静置 5 分钟入味即可。"}]', '["醋", "生抽", "盐", "辣椒酱"]', '["拌盆"]', '["焯水后过一遍凉开水，口感更脆。", "料汁吃之前再淋，放久了会出水。"]', '["黄瓜可以用同季的替代品，用量保持不变。"]', 23.7, 1.5, 0.3, 4.6, 1.8, 7.3, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-06-12 19:12:57', 0, '2026-06-12 19:12:57', '2026-06-12 19:12:57'),
  (1900000000000000462, '凉拌木耳', '凉拌木耳', NULL, 1, NULL, 1, 3, '爽脆', '凉拌木耳爽脆开胃，不用开火也能端上桌。', 1, 12, 8, 1, '[{"no": 1, "text": "木耳洗净，按纹理切好。"}, {"no": 2, "text": "锅中水烧开，木耳焯 30 秒立刻捞出。"}, {"no": 3, "text": "过一遍凉开水，沥干后装盘。"}, {"no": 4, "text": "醋和生抽调成料汁。"}, {"no": 5, "text": "淋上料汁拌匀，静置 5 分钟入味即可。"}]', '["醋", "生抽", "芝麻油", "盐"]', '["拌盆"]', '["焯水后过一遍凉开水，口感更脆。", "料汁吃之前再淋，放久了会出水。"]', '["木耳可以用同季的替代品，用量保持不变。"]', 63.8, 2.7, 4.6, 3.3, 1.3, 3.0, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-08-07 16:49:49', 0, '2026-08-07 16:49:49', '2026-08-07 16:49:49'),
  (1900000000000000470, '凉拌菠菜', '凉拌菠菜', NULL, 1, NULL, 1, 2, '清爽', '凉拌菠菜爽脆开胃，不用开火也能端上桌。', 1, 10, 8, 0, '[{"no": 1, "text": "菠菜洗净，按纹理切好。"}, {"no": 2, "text": "锅中水烧开，菠菜焯 30 秒立刻捞出。"}, {"no": 3, "text": "过一遍凉开水，沥干后装盘。"}, {"no": 4, "text": "生抽和醋调成料汁。"}, {"no": 5, "text": "淋上料汁拌匀，静置 5 分钟入味即可。"}]', '["生抽", "醋", "芝麻油", "盐"]', '["拌盆"]', '["焯水后过一遍凉开水，口感更脆。", "料汁吃之前再淋，放久了会出水。"]', '["菠菜可以用同季的替代品，用量保持不变。"]', 180.3, 8.0, 11.7, 12.2, 4.8, 13.9, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-07-06 18:32:05', 0, '2026-07-06 18:32:05', '2026-07-06 18:32:05'),
  (1900000000000000478, '烤鸡翅', '烤鸡翅', NULL, 1, NULL, 1, 2, '焦香', '鸡翅进烤箱不用守着，外焦里嫩，是懒人友好做法。', 1, 20, 25, 1, '[{"no": 1, "text": "鸡翅洗净，用生抽和料酒腌 30 分钟。"}, {"no": 2, "text": "烤箱预热至 200 度。"}, {"no": 3, "text": "烤盘铺锡纸，把鸡翅摆开不要叠。"}, {"no": 4, "text": "入烤箱烤 25 分钟，中途翻一次面。"}, {"no": 5, "text": "出炉稍晾，撒上孜然或芝麻即可。"}]', '["生抽", "料酒", "蜂蜜", "孜然"]', '["烤箱"]', '["烤盘垫锡纸，事后好清洗。", "腌够时间再进烤箱，味道差很多。"]', '["鸡翅可以用同季的替代品，用量保持不变。"]', 500.0, 50.0, 32.5, 1.2, 0.0, 150.0, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-09-16 17:21:37', 0, '2026-09-16 17:21:37', '2026-09-16 17:21:37'),
  (1900000000000000484, '烤五花肉', '烤五花肉', NULL, 1, NULL, 1, 2, '焦香', '五花肉进烤箱不用守着，外焦里嫩，是懒人友好做法。', 1, 25, 30, 1, '[{"no": 1, "text": "五花肉洗净，用生抽和料酒腌 30 分钟。"}, {"no": 2, "text": "烤箱预热至 200 度。"}, {"no": 3, "text": "烤盘铺锡纸，把五花肉摆开不要叠。"}, {"no": 4, "text": "入烤箱烤 30 分钟，中途翻一次面。"}, {"no": 5, "text": "出炉稍晾，撒上孜然或芝麻即可。"}]', '["生抽", "料酒", "孜然", "五香粉"]', '["烤箱"]', '["烤盘垫锡纸，事后好清洗。", "腌够时间再进烤箱，味道差很多。"]', '["五花肉可以用同季的替代品，用量保持不变。"]', 400.0, 40.0, 26.0, 1.0, 0.0, 120.0, 2, 1, 0.00, 0, 0.0000, 0, 0, '2026-08-13 06:27:01', 0, '2026-08-13 06:27:01', '2026-08-13 06:27:01');
