INSERT INTO t_dish_rating (id, dish_id, user_id, score, taste_score, cooked_flag, comment, weight, deleted, create_time, update_time) VALUES
  (1900000000000000490, 1900000000000000001, 2105666748212461570, 3, 3, 0, '上周做的，中规中矩，照着做没失败，但也不会再做第二次。', 1.00, 0, '2026-08-27 17:49:40', '2026-08-27 17:49:40'),
  (1900000000000000492, 1900000000000000001, 2099751786742411265, 5, 5, 1, NULL, 1.00, 0, '2026-09-24 19:33:35', '2026-09-24 19:33:35'),
  (1900000000000000493, 1900000000000000001, 2105682040150016001, 5, 4, 1, NULL, 1.00, 0, '2026-08-27 19:32:48', '2026-08-27 19:32:48'),
  (1900000000000000495, 1900000000000000001, 2099335487637712897, 4, 3, 1, '第二次做，做出来挺香，唯一的问题是油可以再少放一点。', 1.00, 0, '2026-08-24 03:48:13', '2026-08-24 03:48:13'),
  (1900000000000000497, 1900000000000000001, 2099723461747658753, 5, 4, 1, NULL, 1.00, 0, '2026-09-01 18:49:06', '2026-09-01 18:49:06'),
  (1900000000000000499, 1900000000000000001, 2100442913398906882, 5, 5, 1, '第一次尝试，以前在外面吃过，自己照着做居然还原了八九成。', 1.00, 0, '2026-08-22 19:01:49', '2026-08-22 19:01:49'),
  (1900000000000000500, 1900000000000000001, 2100442916662075394, 5, 5, 0, NULL, 1.00, 0, '2026-08-27 13:52:53', '2026-08-27 13:52:53'),
  (1900000000000000502, 1900000000000000001, 2099698280673062914, 1, 1, 0, NULL, 1.00, 0, '2026-08-24 12:44:49', '2026-08-24 12:44:49'),
  (1900000000000000503, 1900000000000000001, 2105666569564471297, 5, 4, 1, '食材都是冰箱里常备的，不用专门跑超市。', 1.00, 0, '2026-09-27 08:45:52', '2026-09-27 08:45:52'),
  (1900000000000000505, 1900000000000000001, 2100120517366304770, 4, 4, 1, NULL, 1.00, 0, '2026-08-07 11:59:12', '2026-08-07 11:59:12'),
  (1900000000000000506, 1900000000000000001, 2105667472463904769, 5, 5, 1, NULL, 1.00, 0, '2026-08-04 13:04:09', '2026-08-04 13:04:09'),
  (1900000000000000508, 1900000000000000001, 2100412643312459778, 4, 3, 1, NULL, 1.00, 0, '2026-08-17 08:02:54', '2026-08-17 08:02:54'),
  (1900000000000000509, 1900000000000000001, 2105709121059680258, 5, 5, 1, '味道很正，清淡的香气一进门就闻到了。', 1.00, 0, '2026-09-10 20:33:21', '2026-09-10 20:33:21'),
  (1900000000000000510, 1900000000000000001, 2105686689317896193, 5, 5, 1, NULL, 1.00, 0, '2026-09-23 18:05:07', '2026-09-23 18:05:07'),
  (1900000000000000512, 1900000000000000001, 2099723556845113345, 5, 5, 0, NULL, 1.00, 0, '2026-09-24 12:24:30', '2026-09-24 12:24:30'),
  (1900000000000000514, 1900000000000000001, 2099431683098263554, 5, 4, 1, '照着方子，做完给室友分了一份，第二天问我要链接。', 1.00, 0, '2026-08-21 22:35:31', '2026-08-21 22:35:31'),
  (1900000000000000516, 1900000000000000001, 2099424713016459266, 4, 3, 0, NULL, 1.00, 0, '2026-09-17 13:00:25', '2026-09-17 13:00:25'),
