  (1900000000000000520, 1900000000000000001, 2099752498108952577, 4, 3, 1, NULL, 1.00, 0, '2026-08-15 19:34:53', '2026-08-15 19:34:53'),
  (1900000000000000522, 1900000000000000001, 2105686609269604353, 4, 4, 1, '上周做的，做出来的卖相一般，但味道是真的好。', 1.00, 0, '2026-09-29 06:26:34', '2026-09-29 06:26:34'),
  (1900000000000000524, 1900000000000000001, 2105707611408015361, 1, 1, 0, '照着方子，失败了，不知道哪一步出了问题，最后没敢吃。', 1.00, 0, '2026-09-05 19:32:07', '2026-09-05 19:32:07'),
  (1900000000000000525, 1900000000000000001, 2099698692641796098, 4, 4, 1, NULL, 1.00, 0, '2026-08-08 19:19:40', '2026-08-08 19:19:40'),
