  (1900000000000000666, 1900000000000000013, 2099755000149700609, 5, 5, 1, '炒的时间点给得准，照着数秒都不会老。', 1.00, 0, '2026-06-21 06:52:12', '2026-06-21 06:52:12'),
  (1900000000000000668, 1900000000000000013, 2105677244823224321, 3, 3, 1, '第一次尝试，分量和味道都一般，胜在食材好买。', 1.00, 0, '2026-06-08 18:25:52', '2026-06-08 18:25:52'),
  (1900000000000000670, 1900000000000000013, 2099701719658409986, 3, 3, 0, '第二次做，中规中矩，照着做没失败，但也不会再做第二次。', 1.00, 0, '2026-08-25 21:52:15', '2026-08-25 21:52:15'),
