  (1900000000000000873, 1900000000000000039, 2100442913013030913, 3, 2, 0, NULL, 1.00, 0, '2026-09-25 17:41:38', '2026-09-25 17:41:38'),
  (1900000000000000875, 1900000000000000039, 2099756620061208577, 5, 5, 1, NULL, 1.00, 0, '2026-09-30 22:29:24', '2026-09-30 22:29:24'),
  (1900000000000000877, 1900000000000000039, 2099743322662105089, 3, 3, 0, '感觉少了点什么，我自己加了点调料才好吃。', 1.00, 0, '2026-09-10 07:46:45', '2026-09-10 07:46:45'),
  (1900000000000000878, 1900000000000000039, 2105707611408015361, 2, 2, 1, NULL, 1.00, 0, '2026-09-17 20:54:14', '2026-09-17 20:54:14'),
  (1900000000000000879, 1900000000000000039, 2099707575057809409, 5, 5, 1, '上周做的，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-08 15:20:35', '2026-09-08 15:20:35'),
  (1900000000000000880, 1900000000000000039, 2099756277965385729, 4, 4, 1, NULL, 1.00, 0, '2026-09-07 22:21:37', '2026-09-07 22:21:37'),
  (1900000000000000882, 1900000000000000039, 2100442914833358849, 4, 5, 0, '上周做的，挺香，就是最后一步的油温我没控制好。', 1.00, 0, '2026-09-15 14:26:55', '2026-09-15 14:26:55'),
  (1900000000000000883, 1900000000000000039, 2100442919455481857, 5, 5, 1, '家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-23 17:15:42', '2026-09-23 17:15:42'),
  (1900000000000000885, 1900000000000000039, 2099707719815823361, 4, 3, 1, NULL, 1.00, 0, '2026-10-01 21:18:54', '2026-10-01 21:18:54'),
  (1900000000000000887, 1900000000000000039, 2100135297292488705, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 20:57:06', '2026-09-25 20:57:06'),
  (1900000000000000888, 1900000000000000039, 2105666523875917825, 3, 3, 0, '第二次做，中规中矩，照着做没失败，但也不会再做第二次。', 1.00, 0, '2026-09-04 07:41:28', '2026-09-04 07:41:28'),
  (1900000000000000890, 1900000000000000039, 2099751786742411265, 4, 3, 1, NULL, 1.00, 0, '2026-09-15 09:08:55', '2026-09-15 09:08:55'),
  (1900000000000000891, 1900000000000000039, 2105681488087334913, 4, 3, 1, NULL, 1.00, 0, '2026-09-09 13:49:19', '2026-09-09 13:49:19'),
  (1900000000000000893, 1900000000000000039, 2099701719658409986, 5, 5, 0, '今天又做了一次，第二次做了，把鱼香的味道调得更足一点，更合家人口味。', 1.00, 0, '2026-09-18 06:32:20', '2026-09-18 06:32:20'),
  (1900000000000000895, 1900000000000000039, 2099724074103459842, 2, 2, 0, NULL, 1.00, 0, '2026-10-01 20:17:12', '2026-10-01 20:17:12'),
  (1900000000000000896, 1900000000000000039, 2105682212728848385, 5, 5, 1, '第二次做，这道鱼香茄子我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-09-08 20:00:08', '2026-09-08 20:00:08'),
  (1900000000000000898, 1900000000000000039, 2099724470062534657, 5, 5, 1, '第一次尝试，茄子的用量给得刚好，不用自己再摸索，第一次做就很稳。', 1.00, 0, '2026-09-12 19:06:42', '2026-09-12 19:06:42'),
  (1900000000000000900, 1900000000000000039, 2100139475368726530, 2, 2, 0, NULL, 1.00, 0, '2026-09-19 21:12:07', '2026-09-19 21:12:07'),
  (1900000000000000925, 1900000000000000048, 2099698692641796098, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 12:44:50', '2026-09-25 12:44:50'),
  (1900000000000000926, 1900000000000000048, 2105681488087334913, 3, 3, 0, '上周做的，一般般，可能这道菜本身就不是我的菜。', 1.00, 0, '2026-09-19 13:01:47', '2026-09-19 13:01:47'),
  (1900000000000000927, 1900000000000000048, 2099723461747658753, 4, 4, 1, NULL, 1.00, 0, '2026-09-19 19:14:33', '2026-09-19 19:14:33');
INSERT INTO t_dish_rating (id, dish_id, user_id, score, taste_score, cooked_flag, comment, weight, deleted, create_time, update_time) VALUES
  (1900000000000000929, 1900000000000000048, 2099743322662105089, 4, 5, 0, '挺好，就是调料里有一样我家没有，用别的代替了。', 1.00, 0, '2026-09-18 19:50:36', '2026-09-18 19:50:36'),
  (1900000000000000931, 1900000000000000048, 2100442912098672641, 4, 3, 1, '今天又做了一次，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-09-18 19:54:35', '2026-09-18 19:54:35'),
  (1900000000000000933, 1900000000000000048, 2105685510701694978, 5, 5, 1, NULL, 1.00, 0, '2026-09-24 22:26:56', '2026-09-24 22:26:56'),
  (1900000000000000934, 1900000000000000048, 2100139475368726530, 2, 2, 1, NULL, 1.00, 0, '2026-09-27 12:30:38', '2026-09-27 12:30:38'),
  (1900000000000000936, 1900000000000000048, 2105672958714200066, 3, 3, 1, '今天又做了一次，不功不过，做完没什么成就感。', 1.00, 0, '2026-09-25 06:09:44', '2026-09-25 06:09:44'),
  (1900000000000000938, 1900000000000000048, 2099743185026019329, 5, 4, 1, NULL, 1.00, 0, '2026-09-24 18:32:34', '2026-09-24 18:32:34'),
  (1900000000000000939, 1900000000000000048, 2099755347190607873, 5, 5, 1, '第二次做，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-10-01 18:40:45', '2026-10-01 18:40:45'),
  (1900000000000000941, 1900000000000000048, 2105687058194350082, 4, 5, 1, NULL, 1.00, 0, '2026-09-17 10:31:41', '2026-09-17 10:31:41'),
  (1900000000000000943, 1900000000000000048, 2100415018777501697, 5, 4, 1, NULL, 1.00, 0, '2026-09-24 18:05:29', '2026-09-24 18:05:29'),
  (1900000000000000944, 1900000000000000048, 2105666932057194497, 4, 4, 1, NULL, 1.00, 0, '2026-09-24 14:48:15', '2026-09-24 14:48:15'),
  (1900000000000000946, 1900000000000000048, 2100442919002497026, 2, 2, 0, NULL, 1.00, 0, '2026-09-26 09:51:19', '2026-09-26 09:51:19'),
  (1900000000000000947, 1900000000000000048, 2099749705306468354, 4, 5, 1, '第二次做，还可以，主要是我刀工不行，切得不均匀。', 1.00, 0, '2026-09-19 18:19:47', '2026-09-19 18:19:47'),
  (1900000000000000948, 1900000000000000048, 2099428764521185282, 5, 5, 0, '第二次做了，把酱香的味道调得更足一点，更合家人口味。', 1.00, 0, '2026-09-25 20:23:05', '2026-09-25 20:23:05'),
  (1900000000000000949, 1900000000000000048, 2099681709128970242, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 21:39:07', '2026-09-28 21:39:07'),
  (1900000000000000951, 1900000000000000048, 2099755579194339330, 5, 5, 1, NULL, 1.00, 0, '2026-09-27 22:48:49', '2026-09-27 22:48:49'),
  (1900000000000000953, 1900000000000000048, 2105691607936253953, 4, 4, 0, '上周做的，家里人都吃完了，说明没问题，下次多做点。', 1.00, 0, '2026-09-21 12:01:00', '2026-09-21 12:01:00'),
  (1900000000000000955, 1900000000000000048, 2100118309295935490, 4, 3, 1, '成功了，感谢。下次试试加别的配菜。', 1.00, 0, '2026-10-01 01:21:05', '2026-10-01 01:21:05'),
  (1900000000000000956, 1900000000000000048, 2105707611408015361, 3, 3, 0, NULL, 1.00, 0, '2026-09-23 18:13:34', '2026-09-23 18:13:34'),
  (1900000000000000957, 1900000000000000048, 2099702594833494018, 5, 5, 1, NULL, 1.00, 0, '2026-09-20 19:33:01', '2026-09-20 19:33:01'),
  (1900000000000000958, 1900000000000000048, 2099697530345631746, 4, 5, 0, NULL, 1.00, 0, '2026-09-16 21:42:06', '2026-09-16 21:42:06'),
