  (1900000000000000983, 1900000000000000056, 2099698693480656897, 4, 5, 1, NULL, 1.00, 0, '2026-09-28 15:51:07', '2026-09-28 15:51:07'),
  (1900000000000000985, 1900000000000000056, 2100442918482403330, 5, 4, 1, '第一次尝试，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-23 16:57:48', '2026-09-23 16:57:48'),
  (1900000000000000987, 1900000000000000056, 2099701635050909697, 3, 2, 0, NULL, 1.00, 0, '2026-09-02 14:33:59', '2026-09-02 14:33:59'),
  (1900000000000000989, 1900000000000000056, 2099752656385208322, 4, 4, 1, NULL, 1.00, 0, '2026-09-12 23:20:10', '2026-09-12 23:20:10'),
  (1900000000000000991, 1900000000000000056, 2100135297292488705, 3, 3, 1, NULL, 1.00, 0, '2026-09-10 04:07:45', '2026-09-10 04:07:45'),
  (1900000000000000992, 1900000000000000056, 2099681025193185281, 4, 4, 0, '挺好，就是调料里有一样我家没有，用别的代替了。', 1.00, 0, '2026-09-10 08:52:47', '2026-09-10 08:52:47'),
  (1900000000000000993, 1900000000000000056, 2099696755372470274, 5, 5, 1, NULL, 1.00, 0, '2026-08-26 09:31:18', '2026-08-26 09:31:18'),
  (1900000000000000994, 1900000000000000056, 2099699315273641986, 5, 5, 1, '上周做的，调料清单短，厨房小白也不会手忙脚乱。', 1.00, 0, '2026-09-28 18:35:10', '2026-09-28 18:35:10'),
  (1900000000000000995, 1900000000000000056, 2099433163855310849, 5, 4, 1, NULL, 1.00, 0, '2026-09-01 18:47:24', '2026-09-01 18:47:24'),
  (1900000000000000996, 1900000000000000056, 2105709470025773057, 4, 4, 1, NULL, 1.00, 0, '2026-09-25 09:16:48', '2026-09-25 09:16:48'),
  (1900000000000000998, 1900000000000000056, 2105667472463904769, 4, 4, 1, NULL, 1.00, 0, '2026-09-27 12:29:31', '2026-09-27 12:29:31'),
  (1900000000000001010, 1900000000000000061, 2099701705271947265, 4, 3, 1, NULL, 1.00, 0, '2026-09-28 17:49:36', '2026-09-28 17:49:36'),
  (1900000000000001012, 1900000000000000061, 2099701634144940033, 5, 5, 1, '第一次做就成功了，很有成就感。', 1.00, 0, '2026-09-09 13:57:42', '2026-09-09 13:57:42'),
  (1900000000000001013, 1900000000000000061, 2099753672547627009, 4, 4, 1, NULL, 1.00, 0, '2026-09-16 20:04:59', '2026-09-16 20:04:59'),
  (1900000000000001014, 1900000000000000061, 2099701393857458177, 4, 5, 1, NULL, 1.00, 0, '2026-09-13 19:28:14', '2026-09-13 19:28:14'),
  (1900000000000001016, 1900000000000000061, 2099755611784081409, 1, 1, 0, NULL, 1.00, 0, '2026-09-19 13:41:32', '2026-09-19 13:41:32'),
  (1900000000000001018, 1900000000000000061, 2100442914833358849, 4, 3, 0, '第一次尝试，做出来挺香，唯一的问题是油可以再少放一点。', 1.00, 0, '2026-09-02 20:57:43', '2026-09-02 20:57:43'),
  (1900000000000001019, 1900000000000000061, 2099724431911145474, 4, 4, 1, '上周做的，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-09-08 09:37:53', '2026-09-08 09:37:53'),
  (1900000000000001021, 1900000000000000061, 2099428254183440385, 5, 5, 1, '备料到出锅不到半小时，下班回家救急用。', 1.00, 0, '2026-08-28 12:50:01', '2026-08-28 12:50:01'),
  (1900000000000001023, 1900000000000000061, 2099751661219475458, 5, 5, 1, NULL, 1.00, 0, '2026-09-14 00:46:39', '2026-09-14 00:46:39'),
  (1900000000000001025, 1900000000000000061, 2099765319706210306, 5, 5, 1, '第一次尝试，真的省事，洗的锅碗都比其他菜少。', 1.00, 0, '2026-09-30 15:52:50', '2026-09-30 15:52:50'),
  (1900000000000001027, 1900000000000000061, 2099723461747658753, 5, 4, 1, NULL, 1.00, 0, '2026-09-21 19:04:06', '2026-09-21 19:04:06'),
  (1900000000000001029, 1900000000000000061, 2100145795866087425, 5, 5, 1, '分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-09-22 17:26:24', '2026-09-22 17:26:24'),
  (1900000000000001030, 1900000000000000061, 2105666930429804546, 5, 5, 1, '第二次做，炒的时间点给得准，照着数秒都不会老。', 1.00, 0, '2026-08-31 22:26:03', '2026-08-31 22:26:03'),
  (1900000000000001031, 1900000000000000061, 2099698280673062914, 5, 5, 1, '配米饭配面条都行，怎么搭都不出错。', 1.00, 0, '2026-08-29 17:00:09', '2026-08-29 17:00:09'),
  (1900000000000001033, 1900000000000000061, 2105667669579415553, 3, 3, 0, NULL, 1.00, 0, '2026-09-23 19:53:12', '2026-09-23 19:53:12'),
  (1900000000000001034, 1900000000000000061, 2105687200876183554, 5, 4, 1, NULL, 1.00, 0, '2026-09-27 20:43:29', '2026-09-27 20:43:29'),
  (1900000000000001036, 1900000000000000061, 2099751052210728961, 4, 4, 1, '整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-09-11 19:28:20', '2026-09-11 19:28:20'),
  (1900000000000001037, 1900000000000000061, 2099383503295885313, 5, 4, 1, NULL, 1.00, 0, '2026-10-01 21:31:12', '2026-10-01 21:31:12'),
  (1900000000000001039, 1900000000000000061, 2100123699110793218, 5, 5, 1, '照着方子，这个做法把青椒的鲜味全留住了。', 1.00, 0, '2026-09-22 20:22:17', '2026-09-22 20:22:17'),
  (1900000000000001041, 1900000000000000061, 2100442919455481857, 2, 1, 0, '上周做的，调料比例不太对，做完偏甜，家里人都没怎么动。', 1.00, 0, '2026-09-14 18:57:58', '2026-09-14 18:57:58'),
  (1900000000000001043, 1900000000000000061, 2099750963513782274, 5, 5, 1, '上周做的，味道层次挺清楚，不是一味的重口。', 1.00, 0, '2026-09-29 17:45:59', '2026-09-29 17:45:59'),
  (1900000000000001044, 1900000000000000061, 2100442917110865922, 4, 5, 1, NULL, 1.00, 0, '2026-09-07 07:55:42', '2026-09-07 07:55:42'),
  (1900000000000001046, 1900000000000000061, 2099752655537958914, 4, 3, 1, NULL, 1.00, 0, '2026-09-07 18:16:12', '2026-09-07 18:16:12'),
  (1900000000000001048, 1900000000000000061, 2099753790629867522, 5, 5, 1, NULL, 1.00, 0, '2026-09-21 10:06:16', '2026-09-21 10:06:16'),
  (1900000000000001050, 1900000000000000061, 2105672958714200066, 2, 2, 0, '食材用量不太合理，我按量做出来太多了。', 1.00, 0, '2026-09-19 11:55:12', '2026-09-19 11:55:12'),
  (1900000000000001051, 1900000000000000061, 2100442916662075394, 5, 5, 1, NULL, 1.00, 0, '2026-08-30 20:41:07', '2026-08-30 20:41:07'),
  (1900000000000001068, 1900000000000000066, 2099755611784081409, 5, 5, 1, NULL, 1.00, 0, '2026-05-14 07:48:05', '2026-05-14 07:48:05'),
  (1900000000000001070, 1900000000000000066, 2099749704534716417, 5, 5, 1, NULL, 1.00, 0, '2026-08-19 13:52:19', '2026-08-19 13:52:19'),
  (1900000000000001071, 1900000000000000066, 2099383503295885313, 5, 4, 1, NULL, 1.00, 0, '2026-05-24 17:42:52', '2026-05-24 17:42:52'),
  (1900000000000001073, 1900000000000000066, 2099335487637712897, 4, 5, 1, NULL, 1.00, 0, '2026-06-01 14:26:26', '2026-06-01 14:26:26'),
  (1900000000000001075, 1900000000000000066, 2099383437885714434, 4, 3, 1, NULL, 1.00, 0, '2026-04-17 06:05:29', '2026-04-17 06:05:29'),
  (1900000000000001076, 1900000000000000066, 2099751786742411265, 4, 4, 1, '味道好，就是我家锅小，得分两次炒。', 1.00, 0, '2026-09-10 15:18:39', '2026-09-10 15:18:39'),
  (1900000000000001078, 1900000000000000066, 2105709121059680258, 5, 4, 1, '出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-08-01 17:33:34', '2026-08-01 17:33:34'),
  (1900000000000001079, 1900000000000000066, 2099433163855310849, 4, 4, 1, NULL, 1.00, 0, '2026-05-12 18:34:41', '2026-05-12 18:34:41'),
  (1900000000000001080, 1900000000000000066, 2100119371360817154, 4, 4, 1, NULL, 1.00, 0, '2026-06-24 14:23:21', '2026-06-24 14:23:21'),
  (1900000000000001081, 1900000000000000066, 2099383042388013057, 5, 5, 1, '第二次做，第二次做了，把鲜嫩的味道调得更足一点，更合家人口味。', 1.00, 0, '2026-06-13 18:20:28', '2026-06-13 18:20:28'),
  (1900000000000001083, 1900000000000000066, 2099697354612682754, 5, 5, 1, NULL, 1.00, 0, '2026-07-20 23:32:50', '2026-07-20 23:32:50'),
  (1900000000000001085, 1900000000000000066, 2099428168997126145, 5, 5, 0, NULL, 1.00, 0, '2026-04-28 12:08:23', '2026-04-28 12:08:23'),
  (1900000000000001086, 1900000000000000066, 2105709796896272386, 4, 4, 1, '挺好吃的，下次打算把糖减半，家里人不爱甜。', 1.00, 0, '2026-09-29 15:30:18', '2026-09-29 15:30:18'),
  (1900000000000001088, 1900000000000000066, 2099750963513782274, 5, 5, 1, '这个做法把虾仁的鲜味全留住了。', 1.00, 0, '2026-07-20 16:26:40', '2026-07-20 16:26:40'),
  (1900000000000001089, 1900000000000000066, 2105682083112271873, 4, 3, 1, '第一次尝试，蛮好吃的，就是分量偏少，两个人吃略紧。', 1.00, 0, '2026-07-31 20:55:43', '2026-07-31 20:55:43'),
  (1900000000000001091, 1900000000000000066, 2105685384474116098, 4, 5, 1, NULL, 1.00, 0, '2026-07-27 18:51:17', '2026-07-27 18:51:17'),
