  (1900000000000001150, 1900000000000000072, 2099698280673062914, 5, 5, 1, '第一次尝试，比我想象中简单，重点步骤都点出来了。', 1.00, 0, '2026-06-19 21:54:59', '2026-06-19 21:54:59'),
  (1900000000000001152, 1900000000000000072, 2099426390394126337, 5, 5, 0, NULL, 1.00, 0, '2026-07-06 16:59:37', '2026-07-06 16:59:37'),
