  (1900000000000001155, 1900000000000000072, 2099426141265051649, 5, 5, 1, NULL, 1.00, 0, '2026-08-27 07:57:44', '2026-08-27 07:57:44'),
  (1900000000000001156, 1900000000000000072, 2099701393857458177, 4, 5, 0, '做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-09-06 13:09:09', '2026-09-06 13:09:09'),
