  (1900000000000001162, 1900000000000000072, 2099428675450945537, 5, 5, 1, '孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-09-12 20:41:04', '2026-09-12 20:41:04'),
  (1900000000000001164, 1900000000000000072, 2100442917568045058, 3, 2, 0, '第一次尝试，可能是我手艺问题，做出来比预期差一点。', 1.00, 0, '2026-07-28 20:48:59', '2026-07-28 20:48:59'),
  (1900000000000001166, 1900000000000000072, 2100442915739328514, 4, 4, 1, '挺满意的，唯一遗憾是芹菜我没有买到新鲜的。', 1.00, 0, '2026-08-29 17:33:57', '2026-08-29 17:33:57'),
  (1900000000000001167, 1900000000000000072, 2105666569564471297, 5, 5, 1, NULL, 1.00, 0, '2026-06-05 06:44:45', '2026-06-05 06:44:45'),
  (1900000000000001169, 1900000000000000072, 2099424713016459266, 5, 5, 0, '比我想象中简单，重点步骤都点出来了。', 1.00, 0, '2026-08-15 18:18:38', '2026-08-15 18:18:38'),
  (1900000000000001171, 1900000000000000072, 2099751052210728961, 5, 4, 1, '上周做的，以前在外面吃过，自己照着做居然还原了八九成。', 1.00, 0, '2026-08-23 18:51:49', '2026-08-23 18:51:49'),
  (1900000000000001172, 1900000000000000072, 2100442917110865922, 5, 5, 1, NULL, 1.00, 0, '2026-06-15 14:49:10', '2026-06-15 14:49:10'),
  (1900000000000001174, 1900000000000000072, 2105666523875917825, 3, 3, 0, '今天又做了一次，食材搭配有点奇怪，我个人不太习惯。', 1.00, 0, '2026-09-26 16:53:32', '2026-09-26 16:53:32'),
  (1900000000000001175, 1900000000000000072, 2099431683098263554, 5, 5, 1, NULL, 1.00, 0, '2026-06-24 13:08:22', '2026-06-24 13:08:22'),
