  (1900000000000001339, 1900000000000000084, 2099429064401338370, 5, 5, 1, '猪肉的用量给得刚好，不用自己再摸索，第一次做就很稳。', 1.00, 0, '2026-09-08 11:40:01', '2026-09-08 11:40:01'),
  (1900000000000001341, 1900000000000000084, 2099380565668298753, 5, 5, 1, NULL, 1.00, 0, '2026-09-08 18:49:30', '2026-09-08 18:49:30'),
  (1900000000000001343, 1900000000000000084, 2105677399211360257, 5, 5, 1, '第一次尝试，出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-06-05 18:00:35', '2026-06-05 18:00:35'),
  (1900000000000001368, 1900000000000000092, 2100442913856086018, 3, 3, 0, NULL, 1.00, 0, '2026-09-12 17:07:11', '2026-09-12 17:07:11'),
  (1900000000000001370, 1900000000000000092, 2100415018777501697, 5, 4, 1, '今天又做了一次，腌那十分钟真的有用，别偷懒跳过。', 1.00, 0, '2026-09-12 07:36:14', '2026-09-12 07:36:14');
INSERT INTO t_dish_rating (id, dish_id, user_id, score, taste_score, cooked_flag, comment, weight, deleted, create_time, update_time) VALUES
  (1900000000000001371, 1900000000000000092, 2105687200876183554, 4, 4, 1, '挺下饭的，就是有点油，下次我沥一下。', 1.00, 0, '2026-07-29 18:12:52', '2026-07-29 18:12:52'),
  (1900000000000001373, 1900000000000000092, 2100442912098672641, 5, 4, 1, '照着方子，这个做法把五花肉的鲜味全留住了。', 1.00, 0, '2026-09-26 22:40:13', '2026-09-26 22:40:13'),
  (1900000000000001374, 1900000000000000092, 2099429020906405889, 5, 5, 1, NULL, 1.00, 0, '2026-09-02 03:03:39', '2026-09-02 03:03:39'),
  (1900000000000001375, 1900000000000000092, 2105677244823224321, 4, 4, 1, '第二次做，步骤很清楚，新手也能做，只是备料比我预想的花时间。', 1.00, 0, '2026-08-26 15:07:49', '2026-08-26 15:07:49'),
  (1900000000000001377, 1900000000000000092, 2099428168997126145, 4, 5, 1, NULL, 1.00, 0, '2026-09-13 18:54:28', '2026-09-13 18:54:28'),
  (1900000000000001378, 1900000000000000092, 2105707284344578050, 5, 5, 1, NULL, 1.00, 0, '2026-07-31 19:28:32', '2026-07-31 19:28:32'),
  (1900000000000001380, 1900000000000000092, 2099705010635157506, 4, 3, 1, NULL, 1.00, 0, '2026-09-16 21:44:06', '2026-09-16 21:44:06'),
  (1900000000000001381, 1900000000000000092, 2105666571758092290, 3, 3, 0, '上周做的，可能是我手艺问题，做出来比预期差一点。', 1.00, 0, '2026-09-05 14:03:34', '2026-09-05 14:03:34'),
  (1900000000000001383, 1900000000000000092, 2105707611408015361, 4, 4, 1, '整体不错，唯一是步骤里水量说得有点模糊。', 1.00, 0, '2026-08-31 14:42:46', '2026-08-31 14:42:46'),
  (1900000000000001385, 1900000000000000092, 2100442915739328514, 5, 5, 1, NULL, 1.00, 0, '2026-08-25 20:52:30', '2026-08-25 20:52:30'),
  (1900000000000001387, 1900000000000000092, 2099701719658409986, 3, 2, 1, '做法没问题，就是味道偏淡，得自己加重口。', 1.00, 0, '2026-09-09 16:11:41', '2026-09-09 16:11:41'),
  (1900000000000001389, 1900000000000000092, 2100413312169730049, 4, 4, 1, NULL, 1.00, 0, '2026-08-01 09:59:00', '2026-08-01 09:59:00'),
  (1900000000000001390, 1900000000000000092, 2105677589800534018, 5, 4, 1, NULL, 1.00, 0, '2026-09-10 12:10:25', '2026-09-10 12:10:25'),
  (1900000000000001392, 1900000000000000092, 2100442916662075394, 4, 3, 1, NULL, 1.00, 0, '2026-08-16 20:29:55', '2026-08-16 20:29:55'),
  (1900000000000001393, 1900000000000000092, 2099698692641796098, 5, 5, 1, '上周做的，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-08-07 20:57:31', '2026-08-07 20:57:31'),
  (1900000000000001394, 1900000000000000092, 2099428007537393665, 4, 4, 0, NULL, 1.00, 0, '2026-08-05 08:34:31', '2026-08-05 08:34:31'),
  (1900000000000001396, 1900000000000000092, 2099433163855310849, 5, 5, 1, '配米饭配面条都行，怎么搭都不出错。', 1.00, 0, '2026-09-09 06:18:51', '2026-09-09 06:18:51'),
  (1900000000000001398, 1900000000000000092, 2099702580669329409, 5, 5, 1, NULL, 1.00, 0, '2026-08-08 11:17:13', '2026-08-08 11:17:13'),
  (1900000000000001400, 1900000000000000092, 2099427479453548545, 4, 4, 1, '可以，下次我会先把五花肉焯水再炒，口感应该更好。', 1.00, 0, '2026-09-05 20:40:56', '2026-09-05 20:40:56'),
  (1900000000000001401, 1900000000000000092, 2105666748212461570, 2, 3, 1, NULL, 1.00, 0, '2026-09-17 21:55:03', '2026-09-17 21:55:03'),
  (1900000000000001402, 1900000000000000092, 2100442914309070850, 5, 5, 1, NULL, 1.00, 0, '2026-09-29 22:06:11', '2026-09-29 22:06:11'),
  (1900000000000001404, 1900000000000000092, 2099701635050909697, 5, 5, 1, NULL, 1.00, 0, '2026-09-20 18:52:47', '2026-09-20 18:52:47'),
  (1900000000000001405, 1900000000000000092, 2105682040150016001, 4, 4, 1, NULL, 1.00, 0, '2026-08-15 21:03:12', '2026-08-15 21:03:12'),
  (1900000000000001406, 1900000000000000092, 2105685510701694978, 5, 4, 1, NULL, 1.00, 0, '2026-08-05 07:54:26', '2026-08-05 07:54:26'),
  (1900000000000001407, 1900000000000000092, 2100442919455481857, 5, 5, 1, NULL, 1.00, 0, '2026-09-15 06:47:58', '2026-09-15 06:47:58'),
  (1900000000000001409, 1900000000000000092, 2100427162000613377, 3, 4, 1, NULL, 1.00, 0, '2026-09-22 19:44:56', '2026-09-22 19:44:56'),
  (1900000000000001410, 1900000000000000092, 2099723556845113345, 1, 1, 0, '今天又做了一次，失败了，不知道哪一步出了问题，最后没敢吃。', 1.00, 0, '2026-07-31 19:27:53', '2026-07-31 19:27:53'),
  (1900000000000001412, 1900000000000000092, 2100145795866087425, 4, 4, 1, NULL, 1.00, 0, '2026-08-21 11:27:07', '2026-08-21 11:27:07'),
  (1900000000000001413, 1900000000000000092, 2100140070104256514, 3, 4, 0, '照着方子，中规中矩，照着做没失败，但也不会再做第二次。', 1.00, 0, '2026-08-04 09:28:18', '2026-08-04 09:28:18'),
  (1900000000000001414, 1900000000000000092, 2099698693480656897, 4, 4, 1, '满意，就是这个量我家三口人吃有点不够。', 1.00, 0, '2026-08-26 12:04:06', '2026-08-26 12:04:06'),
  (1900000000000001415, 1900000000000000092, 2105677399211360257, 5, 5, 1, '五花肉处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-09-25 16:19:42', '2026-09-25 16:19:42'),
  (1900000000000001417, 1900000000000000092, 2099433596644569090, 3, 3, 0, '做出来偏咸，下次要减量，这次只能凑合吃。', 1.00, 0, '2026-08-21 13:21:24', '2026-08-21 13:21:24'),
  (1900000000000001419, 1900000000000000092, 2099756278732943361, 2, 2, 0, '第二次做，有点失望，味道和想象中差不少。', 1.00, 0, '2026-09-05 19:44:20', '2026-09-05 19:44:20'),
  (1900000000000001421, 1900000000000000092, 2100406228522950657, 5, 5, 1, '连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-08-19 23:31:16', '2026-08-19 23:31:16'),
  (1900000000000001423, 1900000000000000092, 2099751661219475458, 5, 4, 1, '今天又做了一次，这道回锅肉我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-09-12 13:55:56', '2026-09-12 13:55:56'),
  (1900000000000001425, 1900000000000000092, 2100417387170947073, 4, 4, 1, NULL, 1.00, 0, '2026-08-24 18:51:27', '2026-08-24 18:51:27'),
  (1900000000000001426, 1900000000000000092, 2100442919979769857, 1, 1, 0, '第二次做，咸得没法入口，建议把用量再核一下。', 1.00, 0, '2026-08-16 15:58:36', '2026-08-16 15:58:36'),
  (1900000000000001428, 1900000000000000092, 2099431876065607681, 3, 4, 1, NULL, 1.00, 0, '2026-09-05 20:18:05', '2026-09-05 20:18:05'),
  (1900000000000001430, 1900000000000000092, 2105667669579415553, 5, 4, 0, NULL, 1.00, 0, '2026-09-28 06:27:01', '2026-09-28 06:27:01'),
  (1900000000000001432, 1900000000000000092, 2099428254183440385, 5, 5, 1, '第一次尝试，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-06 18:52:14', '2026-09-06 18:52:14'),
  (1900000000000001434, 1900000000000000092, 2099746243478941698, 3, 3, 0, '第一次尝试，分量和味道都一般，胜在食材好买。', 1.00, 0, '2026-07-30 12:33:08', '2026-07-30 12:33:08'),
  (1900000000000001436, 1900000000000000092, 2100135297292488705, 4, 4, 1, NULL, 1.00, 0, '2026-09-11 18:02:55', '2026-09-11 18:02:55'),
  (1900000000000001438, 1900000000000000092, 2099697354612682754, 4, 4, 1, NULL, 1.00, 0, '2026-09-03 16:12:55', '2026-09-03 16:12:55'),
  (1900000000000001439, 1900000000000000092, 2100442917568045058, 3, 3, 0, NULL, 1.00, 0, '2026-09-15 20:38:28', '2026-09-15 20:38:28'),
  (1900000000000001441, 1900000000000000092, 2105666930429804546, 4, 4, 1, NULL, 1.00, 0, '2026-09-17 10:05:10', '2026-09-17 10:05:10'),
  (1900000000000001461, 1900000000000000099, 2100121454612893698, 2, 2, 0, '第二次做，味道比较寡淡，需要自己大改，不太推荐照搬。', 1.00, 0, '2026-09-30 11:39:28', '2026-09-30 11:39:28'),
  (1900000000000001463, 1900000000000000099, 2099390475495927810, 4, 4, 1, NULL, 1.00, 0, '2026-10-01 21:34:05', '2026-10-01 21:34:05'),
  (1900000000000001465, 1900000000000000099, 2100442912622960641, 4, 3, 1, NULL, 1.00, 0, '2026-09-12 22:51:31', '2026-09-12 22:51:31'),
  (1900000000000001466, 1900000000000000099, 2100118309295935490, 4, 4, 1, '不错，下次提前腌久一点应该更入味。', 1.00, 0, '2026-09-13 20:15:13', '2026-09-13 20:15:13'),
  (1900000000000001467, 1900000000000000099, 2099755000149700609, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 18:11:19', '2026-10-01 18:11:19'),
  (1900000000000001469, 1900000000000000099, 2105677399211360257, 5, 5, 1, NULL, 1.00, 0, '2026-09-24 22:06:31', '2026-09-24 22:06:31'),
  (1900000000000001471, 1900000000000000099, 2105686689317896193, 4, 5, 1, NULL, 1.00, 0, '2026-09-10 20:10:20', '2026-09-10 20:10:20'),
  (1900000000000001473, 1900000000000000099, 2099724431911145474, 5, 5, 0, NULL, 1.00, 0, '2026-09-22 18:52:09', '2026-09-22 18:52:09'),
  (1900000000000001474, 1900000000000000099, 2099750963513782274, 5, 5, 1, '第一次尝试，我把辣度减了一半给孩子吃，照样很好吃。', 1.00, 0, '2026-09-30 12:35:18', '2026-09-30 12:35:18'),
  (1900000000000001476, 1900000000000000099, 2099344911148261377, 4, 4, 1, '今天又做了一次，可以，下次我会先把鸡胸肉焯水再炒，口感应该更好。', 1.00, 0, '2026-09-11 13:51:34', '2026-09-11 13:51:34'),
  (1900000000000001477, 1900000000000000099, 2099701394633404418, 3, 3, 0, '第二次做，味道普通，感觉外卖随便点一个都比这个强。', 1.00, 0, '2026-09-27 16:57:59', '2026-09-27 16:57:59'),
  (1900000000000001478, 1900000000000000099, 2099723461747658753, 4, 4, 0, NULL, 1.00, 0, '2026-09-14 17:24:21', '2026-09-14 17:24:21'),
  (1900000000000001479, 1900000000000000099, 2099431876065607681, 4, 4, 1, '第二次做，整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-09-15 13:45:13', '2026-09-15 13:45:13'),
  (1900000000000001481, 1900000000000000099, 2105677244823224321, 5, 4, 1, NULL, 1.00, 0, '2026-09-19 13:55:27', '2026-09-19 13:55:27'),
  (1900000000000001483, 1900000000000000099, 2099429064401338370, 4, 4, 1, '上周做的，整体不错，唯一是步骤里水量说得有点模糊。', 1.00, 0, '2026-09-14 17:44:09', '2026-09-14 17:44:09'),
  (1900000000000001484, 1900000000000000099, 2099701634144940033, 3, 3, 0, '没有想象中好，主要是鸡胸肉的味道没出来。', 1.00, 0, '2026-09-13 22:46:36', '2026-09-13 22:46:36'),
  (1900000000000001486, 1900000000000000099, 2099428007537393665, 4, 4, 1, '今天又做了一次，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-09-26 19:23:20', '2026-09-26 19:23:20'),
  (1900000000000001488, 1900000000000000099, 2099437330086760449, 5, 5, 1, NULL, 1.00, 0, '2026-09-24 12:31:56', '2026-09-24 12:31:56'),
  (1900000000000001490, 1900000000000000099, 2099428168997126145, 5, 5, 1, NULL, 1.00, 0, '2026-09-16 07:06:42', '2026-09-16 07:06:42'),
  (1900000000000001492, 1900000000000000099, 2099698693480656897, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 12:32:47', '2026-10-01 12:32:47'),
  (1900000000000001494, 1900000000000000099, 2099428675450945537, 4, 4, 1, '还可以，主要是我刀工不行，切得不均匀。', 1.00, 0, '2026-09-26 17:04:07', '2026-09-26 17:04:07'),
  (1900000000000001514, 1900000000000000107, 2099701705271947265, 5, 5, 1, '牛肉处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-09-03 11:53:08', '2026-09-03 11:53:08'),
  (1900000000000001516, 1900000000000000107, 2099428764521185282, 3, 4, 1, NULL, 1.00, 0, '2026-08-21 19:37:20', '2026-08-21 19:37:20'),
  (1900000000000001518, 1900000000000000107, 2099383579003072514, 5, 5, 1, NULL, 1.00, 0, '2026-08-23 19:15:55', '2026-08-23 19:15:55'),
  (1900000000000001520, 1900000000000000107, 2099681025193185281, 5, 5, 1, NULL, 1.00, 0, '2026-08-03 21:31:53', '2026-08-03 21:31:53'),
