  (1900000000000001536, 1900000000000000107, 2099751786029379585, 4, 4, 1, NULL, 1.00, 0, '2026-08-23 18:17:24', '2026-08-23 18:17:24'),
  (1900000000000001538, 1900000000000000107, 2099751661219475458, 5, 5, 1, '孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-09-27 21:08:06', '2026-09-27 21:08:06'),
  (1900000000000001540, 1900000000000000107, 2099743185026019329, 5, 4, 1, '牛肉的用量给得刚好，不用自己再摸索，第一次做就很稳。', 1.00, 0, '2026-09-30 12:24:59', '2026-09-30 12:24:59'),
  (1900000000000001542, 1900000000000000107, 2099424713016459266, 4, 4, 1, NULL, 1.00, 0, '2026-09-03 09:09:38', '2026-09-03 09:09:38'),
  (1900000000000001543, 1900000000000000107, 2105667669579415553, 4, 4, 1, '今天又做了一次，挺满意的，唯一遗憾是牛肉我没有买到新鲜的。', 1.00, 0, '2026-09-11 03:30:55', '2026-09-11 03:30:55'),
  (1900000000000001545, 1900000000000000107, 2099697530345631746, 1, 1, 0, NULL, 1.00, 0, '2026-08-31 17:52:40', '2026-08-31 17:52:40'),
  (1900000000000001547, 1900000000000000107, 2099427479453548545, 5, 5, 1, NULL, 1.00, 0, '2026-09-02 12:24:37', '2026-09-02 12:24:37'),
