  (1900000000000001553, 1900000000000000107, 2099701634144940033, 3, 4, 0, '做法没问题，就是味道偏淡，得自己加重口。', 1.00, 0, '2026-09-11 22:47:05', '2026-09-11 22:47:05'),
  (1900000000000001554, 1900000000000000107, 2099429519441379329, 5, 5, 1, '照着方子，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-09-30 11:28:43', '2026-09-30 11:28:43'),
  (1900000000000001571, 1900000000000000114, 2100442918482403330, 4, 4, 1, NULL, 1.00, 0, '2026-08-29 00:04:01', '2026-08-29 00:04:01'),
  (1900000000000001572, 1900000000000000114, 2099424960438452226, 4, 4, 1, '整体挺好，下次我会少放一点盐，偏咸了些。', 1.00, 0, '2026-09-17 12:28:51', '2026-09-17 12:28:51'),
  (1900000000000001574, 1900000000000000114, 2099424713016459266, 4, 4, 1, NULL, 1.00, 0, '2026-09-14 16:59:45', '2026-09-14 16:59:45'),
  (1900000000000001576, 1900000000000000114, 2099743185026019329, 4, 4, 0, '挺好吃的，就是感觉少了一点点酸味。', 1.00, 0, '2026-09-01 21:15:57', '2026-09-01 21:15:57'),
