  (1900000000000001580, 1900000000000000114, 2099428764521185282, 1, 1, 0, NULL, 1.00, 0, '2026-09-11 12:16:52', '2026-09-11 12:16:52'),
  (1900000000000001581, 1900000000000000114, 2100118309295935490, 4, 4, 1, '今天又做了一次，可以，下次我会先把土豆焯水再炒，口感应该更好。', 1.00, 0, '2026-09-15 14:28:01', '2026-09-15 14:28:01'),
  (1900000000000001582, 1900000000000000114, 2099707575057809409, 5, 5, 1, NULL, 1.00, 0, '2026-08-13 16:50:43', '2026-08-13 16:50:43'),
  (1900000000000001583, 1900000000000000114, 2100123699110793218, 1, 1, 0, NULL, 1.00, 0, '2026-08-17 00:03:39', '2026-08-17 00:03:39'),
  (1900000000000001584, 1900000000000000114, 2105709796896272386, 4, 4, 1, '家里人都吃完了，说明没问题，下次多做点。', 1.00, 0, '2026-08-21 20:21:17', '2026-08-21 20:21:17'),
  (1900000000000001586, 1900000000000000114, 2099743322662105089, 5, 5, 1, NULL, 1.00, 0, '2026-08-24 19:25:59', '2026-08-24 19:25:59'),
  (1900000000000001588, 1900000000000000114, 2099751661219475458, 2, 2, 0, NULL, 1.00, 0, '2026-08-17 14:12:01', '2026-08-17 14:12:01'),
  (1900000000000001590, 1900000000000000114, 2099335487637712897, 5, 5, 1, NULL, 1.00, 0, '2026-09-19 23:19:26', '2026-09-19 23:19:26'),
  (1900000000000001592, 1900000000000000114, 2099428254183440385, 5, 5, 1, '比我想象中简单，重点步骤都点出来了。', 1.00, 0, '2026-09-06 07:08:01', '2026-09-06 07:08:01'),
  (1900000000000001594, 1900000000000000114, 2100135297292488705, 4, 4, 1, NULL, 1.00, 0, '2026-09-17 02:05:21', '2026-09-17 02:05:21'),
  (1900000000000001609, 1900000000000000121, 2100442917958115330, 4, 4, 1, NULL, 1.00, 0, '2026-08-24 18:47:55', '2026-08-24 18:47:55'),
  (1900000000000001610, 1900000000000000121, 2099701634144940033, 4, 4, 1, '第一次做稍微咸了点，第二次减量正好。', 1.00, 0, '2026-08-23 09:30:33', '2026-08-23 09:30:33'),
  (1900000000000001611, 1900000000000000121, 2099431876065607681, 4, 4, 1, '不错，就是最后装盘不太好看，不影响吃。', 1.00, 0, '2026-08-18 09:55:41', '2026-08-18 09:55:41'),
  (1900000000000001613, 1900000000000000121, 2100442914833358849, 4, 4, 1, '上周做的，不错，下次提前腌久一点应该更入味。', 1.00, 0, '2026-09-15 22:43:20', '2026-09-15 22:43:20'),
  (1900000000000001615, 1900000000000000121, 2105677589800534018, 4, 5, 1, NULL, 1.00, 0, '2026-09-13 10:55:28', '2026-09-13 10:55:28'),
  (1900000000000001616, 1900000000000000121, 2100145795866087425, 4, 4, 1, '上周做的，挺满意的，唯一遗憾是山药我没有买到新鲜的。', 1.00, 0, '2026-09-28 18:38:29', '2026-09-28 18:38:29'),
  (1900000000000001618, 1900000000000000121, 2099433163855310849, 4, 4, 1, NULL, 1.00, 0, '2026-09-18 15:47:48', '2026-09-18 15:47:48'),
  (1900000000000001620, 1900000000000000121, 2099383042388013057, 3, 3, 0, NULL, 1.00, 0, '2026-08-18 19:59:13', '2026-08-18 19:59:13'),
  (1900000000000001622, 1900000000000000121, 2100118309295935490, 3, 3, 0, NULL, 1.00, 0, '2026-08-22 10:20:44', '2026-08-22 10:20:44'),
  (1900000000000001624, 1900000000000000121, 2100406228522950657, 5, 4, 1, NULL, 1.00, 0, '2026-08-28 07:57:26', '2026-08-28 07:57:26'),
  (1900000000000001625, 1900000000000000121, 2105682083112271873, 5, 5, 1, NULL, 1.00, 0, '2026-09-03 22:54:10', '2026-09-03 22:54:10'),
  (1900000000000001627, 1900000000000000121, 2099752656385208322, 5, 5, 1, '腌那十分钟真的有用，别偷懒跳过。', 1.00, 0, '2026-09-28 16:19:11', '2026-09-28 16:19:11'),
  (1900000000000001628, 1900000000000000121, 2099751661219475458, 5, 5, 1, '照着方子，孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-08-21 19:44:12', '2026-08-21 19:44:12'),
  (1900000000000001630, 1900000000000000121, 2099379216679469057, 5, 5, 0, '第一次做就成功了，很有成就感。', 1.00, 0, '2026-09-28 07:36:25', '2026-09-28 07:36:25'),
  (1900000000000001631, 1900000000000000121, 2105670358598041602, 5, 5, 1, '今天又做了一次，按这个量放调料，咸淡刚刚好，不用再补救。', 1.00, 0, '2026-09-17 20:19:19', '2026-09-17 20:19:19'),
  (1900000000000001632, 1900000000000000121, 2100123699110793218, 5, 4, 1, NULL, 1.00, 0, '2026-09-17 12:16:26', '2026-09-17 12:16:26'),
  (1900000000000001634, 1900000000000000121, 2099756278732943361, 4, 4, 1, NULL, 1.00, 0, '2026-09-18 10:20:46', '2026-09-18 10:20:46'),
  (1900000000000001636, 1900000000000000121, 2099428764521185282, 5, 5, 1, '调料清单短，厨房小白也不会手忙脚乱。', 1.00, 0, '2026-09-19 08:57:03', '2026-09-19 08:57:03'),
  (1900000000000001638, 1900000000000000121, 2100146248997720065, 4, 5, 1, NULL, 1.00, 0, '2026-08-22 20:33:37', '2026-08-22 20:33:37'),
  (1900000000000001640, 1900000000000000121, 2099380565668298753, 3, 2, 0, NULL, 1.00, 0, '2026-09-01 11:19:40', '2026-09-01 11:19:40'),
  (1900000000000001642, 1900000000000000121, 2099697410912825345, 3, 3, 1, '照着方子，不功不过，做完没什么成就感。', 1.00, 0, '2026-08-16 20:43:24', '2026-08-16 20:43:24'),
  (1900000000000001644, 1900000000000000121, 2099751660376420354, 4, 4, 1, '照着方子，挺满意的，唯一遗憾是山药我没有买到新鲜的。', 1.00, 0, '2026-08-22 06:20:18', '2026-08-22 06:20:18'),
