  (1900000000000001807, 1900000000000000138, 2099752655537958914, 5, 4, 1, NULL, 1.00, 0, '2026-06-29 12:49:05', '2026-06-29 12:49:05'),
  (1900000000000001809, 1900000000000000138, 2105707494147858434, 5, 5, 1, '上周做的，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-09-20 19:36:18', '2026-09-20 19:36:18'),
