  (1900000000000001816, 1900000000000000138, 2100121454612893698, 5, 4, 1, '照着方子，味道很正，酱香的香气一进门就闻到了。', 1.00, 0, '2026-08-19 03:59:46', '2026-08-19 03:59:46'),
  (1900000000000001818, 1900000000000000138, 2099752497320423425, 4, 4, 0, NULL, 1.00, 0, '2026-07-13 10:56:14', '2026-07-13 10:56:14'),
  (1900000000000001819, 1900000000000000138, 2099723811162542082, 4, 4, 1, '照着方子，满意，就是这个量我家三口人吃有点不够。', 1.00, 0, '2026-06-24 13:39:16', '2026-06-24 13:39:16'),
  (1900000000000001821, 1900000000000000138, 2099702594833494018, 5, 4, 1, '按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-09-10 13:55:46', '2026-09-10 13:55:46'),
  (1900000000000001823, 1900000000000000138, 2099753672547627009, 4, 4, 1, '挺香，就是最后一步的油温我没控制好。', 1.00, 0, '2026-09-18 19:09:16', '2026-09-18 19:09:16'),
  (1900000000000001825, 1900000000000000138, 2099765319706210306, 5, 5, 1, '今天又做了一次，豆腐处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-08-02 08:22:55', '2026-08-02 08:22:55'),
  (1900000000000001827, 1900000000000000138, 2099756277965385729, 3, 2, 0, '感觉少了点什么，我自己加了点调料才好吃。', 1.00, 0, '2026-06-21 17:32:44', '2026-06-21 17:32:44'),
  (1900000000000001828, 1900000000000000138, 2099701394633404418, 4, 5, 1, '今天又做了一次，还可以，主要是我刀工不行，切得不均匀。', 1.00, 0, '2026-07-05 21:34:22', '2026-07-05 21:34:22'),
  (1900000000000001829, 1900000000000000138, 2099698280673062914, 5, 5, 1, NULL, 1.00, 0, '2026-08-11 19:43:01', '2026-08-11 19:43:01'),
