  (1900000000000002065, 1900000000000000159, 2099723461747658753, 5, 5, 1, '按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-09-29 19:19:06', '2026-09-29 19:19:06'),
  (1900000000000002067, 1900000000000000159, 2099380565668298753, 5, 5, 1, NULL, 1.00, 0, '2026-09-29 13:02:56', '2026-09-29 13:02:56'),
  (1900000000000002069, 1900000000000000159, 2105681825976270849, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 08:39:32', '2026-10-01 08:39:32'),
  (1900000000000002071, 1900000000000000159, 2099696755372470274, 5, 5, 1, NULL, 1.00, 0, '2026-09-19 07:30:05', '2026-09-19 07:30:05'),
  (1900000000000002073, 1900000000000000159, 2099426804636172290, 5, 5, 1, '今天又做了一次，孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-09-20 16:31:23', '2026-09-20 16:31:23'),
  (1900000000000002074, 1900000000000000159, 2100442916133593090, 4, 3, 1, NULL, 1.00, 0, '2026-09-28 14:39:39', '2026-09-28 14:39:39'),
  (1900000000000002076, 1900000000000000159, 2100413312169730049, 5, 5, 1, NULL, 1.00, 0, '2026-09-21 19:49:27', '2026-09-21 19:49:27'),
  (1900000000000002077, 1900000000000000159, 2099424713016459266, 5, 5, 1, NULL, 1.00, 0, '2026-09-20 19:39:35', '2026-09-20 19:39:35'),
  (1900000000000002079, 1900000000000000159, 2099743112946905090, 3, 4, 0, '今天又做了一次，分量和味道都一般，胜在食材好买。', 1.00, 0, '2026-09-25 19:28:30', '2026-09-25 19:28:30'),
  (1900000000000002081, 1900000000000000159, 2100442912622960641, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 08:23:39', '2026-10-01 08:23:39'),
  (1900000000000002083, 1900000000000000159, 2099743322662105089, 4, 4, 1, NULL, 1.00, 0, '2026-09-29 18:11:07', '2026-09-29 18:11:07'),
  (1900000000000002085, 1900000000000000159, 2099681025193185281, 5, 5, 1, NULL, 1.00, 0, '2026-09-17 21:31:47', '2026-09-17 21:31:47'),
  (1900000000000002087, 1900000000000000159, 2099697355321520129, 5, 5, 0, '按这个量放调料，咸淡刚刚好，不用再补救。', 1.00, 0, '2026-09-17 20:54:46', '2026-09-17 20:54:46'),
  (1900000000000002089, 1900000000000000159, 2100427162000613377, 5, 5, 1, NULL, 1.00, 0, '2026-09-22 11:24:08', '2026-09-22 11:24:08'),
  (1900000000000002090, 1900000000000000159, 2099429064401338370, 3, 3, 0, '味道普通，感觉外卖随便点一个都比这个强。', 1.00, 0, '2026-10-01 19:04:08', '2026-10-01 19:04:08'),
  (1900000000000002092, 1900000000000000159, 2099697530345631746, 5, 5, 0, NULL, 1.00, 0, '2026-09-18 20:23:06', '2026-09-18 20:23:06'),
  (1900000000000002094, 1900000000000000159, 2099749704534716417, 4, 3, 1, '今天又做了一次，家里人都吃完了，说明没问题，下次多做点。', 1.00, 0, '2026-09-21 17:47:16', '2026-09-21 17:47:16'),
  (1900000000000002107, 1900000000000000167, 2099751052210728961, 5, 5, 1, '今天又做了一次，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-09-29 15:16:58', '2026-09-29 15:16:58'),
  (1900000000000002109, 1900000000000000167, 2099707575057809409, 4, 4, 1, NULL, 1.00, 0, '2026-07-24 07:09:10', '2026-07-24 07:09:10'),
  (1900000000000002111, 1900000000000000167, 2099383579003072514, 4, 5, 1, NULL, 1.00, 0, '2026-08-09 10:38:22', '2026-08-09 10:38:22'),
  (1900000000000002112, 1900000000000000167, 2099698280006168577, 5, 5, 1, NULL, 1.00, 0, '2026-07-20 19:31:46', '2026-07-20 19:31:46'),
  (1900000000000002113, 1900000000000000167, 2100120517366304770, 5, 5, 1, NULL, 1.00, 0, '2026-07-31 19:35:34', '2026-07-31 19:35:34'),
  (1900000000000002115, 1900000000000000167, 2099681025193185281, 3, 2, 0, '上周做的，感觉少了点什么，我自己加了点调料才好吃。', 1.00, 0, '2026-08-26 07:22:28', '2026-08-26 07:22:28'),
  (1900000000000002116, 1900000000000000167, 2099697354612682754, 4, 4, 1, NULL, 1.00, 0, '2026-08-15 22:14:20', '2026-08-15 22:14:20'),
  (1900000000000002117, 1900000000000000167, 2099756278732943361, 5, 5, 1, '今天又做了一次，分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-09-03 21:54:30', '2026-09-03 21:54:30'),
  (1900000000000002119, 1900000000000000167, 2099755579194339330, 5, 5, 0, '配米饭配面条都行，怎么搭都不出错。', 1.00, 0, '2026-09-28 18:27:21', '2026-09-28 18:27:21'),
  (1900000000000002121, 1900000000000000167, 2100422849102667778, 2, 1, 0, NULL, 1.00, 0, '2026-07-20 22:42:08', '2026-07-20 22:42:08'),
  (1900000000000002122, 1900000000000000167, 2105667474145820673, 4, 4, 1, NULL, 1.00, 0, '2026-08-29 14:43:52', '2026-08-29 14:43:52'),
  (1900000000000002124, 1900000000000000167, 2100442913013030913, 3, 3, 0, '分量和味道都一般，胜在食材好买。', 1.00, 0, '2026-09-08 10:29:36', '2026-09-08 10:29:36'),
  (1900000000000002125, 1900000000000000167, 2099335487637712897, 5, 4, 1, NULL, 1.00, 0, '2026-08-30 05:19:33', '2026-08-30 05:19:33'),
  (1900000000000002126, 1900000000000000167, 2105667671450075137, 5, 4, 1, NULL, 1.00, 0, '2026-07-29 18:31:12', '2026-07-29 18:31:12'),
  (1900000000000002128, 1900000000000000167, 2100427162000613377, 5, 4, 1, '我妈尝了一口说这个可以上桌待客了。', 1.00, 0, '2026-07-31 19:08:20', '2026-07-31 19:08:20'),
  (1900000000000002130, 1900000000000000167, 2105687058194350082, 4, 4, 1, '今天又做了一次，不错，就是最后装盘不太好看，不影响吃。', 1.00, 0, '2026-09-12 17:05:42', '2026-09-12 17:05:42'),
  (1900000000000002131, 1900000000000000167, 2099723556845113345, 5, 5, 1, NULL, 1.00, 0, '2026-07-26 08:18:50', '2026-07-26 08:18:50'),
  (1900000000000002133, 1900000000000000167, 2099752655537958914, 4, 4, 1, NULL, 1.00, 0, '2026-07-30 21:12:01', '2026-07-30 21:12:01'),
  (1900000000000002134, 1900000000000000167, 2099756620061208577, 5, 5, 1, NULL, 1.00, 0, '2026-09-18 17:54:30', '2026-09-18 17:54:30'),
  (1900000000000002136, 1900000000000000167, 2100442916133593090, 2, 2, 1, '照着方子，调料比例不太对，做完偏甜，家里人都没怎么动。', 1.00, 0, '2026-09-19 17:02:09', '2026-09-19 17:02:09'),
  (1900000000000002138, 1900000000000000167, 2100413312169730049, 5, 5, 1, NULL, 1.00, 0, '2026-08-16 20:32:21', '2026-08-16 20:32:21'),
  (1900000000000002139, 1900000000000000167, 2099743185026019329, 1, 1, 1, NULL, 1.00, 0, '2026-08-21 19:22:58', '2026-08-21 19:22:58'),
  (1900000000000002140, 1900000000000000167, 2099431487983435778, 4, 4, 1, NULL, 1.00, 0, '2026-08-16 18:01:13', '2026-08-16 18:01:13'),
  (1900000000000002142, 1900000000000000167, 2100442917568045058, 4, 4, 1, '第二次做，不错，下次提前腌久一点应该更入味。', 1.00, 0, '2026-09-14 18:11:13', '2026-09-14 18:11:13'),
  (1900000000000002144, 1900000000000000167, 2100442919979769857, 4, 4, 1, NULL, 1.00, 0, '2026-09-06 16:08:21', '2026-09-06 16:08:21'),
  (1900000000000002146, 1900000000000000167, 2100442915294732290, 2, 2, 0, '上周做的，感觉这道菜不太适合新手，我翻车了。', 1.00, 0, '2026-09-01 11:01:55', '2026-09-01 11:01:55'),
  (1900000000000002148, 1900000000000000167, 2099743322662105089, 3, 4, 0, '今天又做了一次，做出来偏咸，下次要减量，这次只能凑合吃。', 1.00, 0, '2026-09-23 19:55:54', '2026-09-23 19:55:54'),
  (1900000000000002150, 1900000000000000167, 2099428675450945537, 5, 4, 1, NULL, 1.00, 0, '2026-10-01 22:52:39', '2026-10-01 22:52:39'),
  (1900000000000002152, 1900000000000000167, 2105682083112271873, 5, 5, 1, NULL, 1.00, 0, '2026-09-21 18:29:23', '2026-09-21 18:29:23'),
  (1900000000000002153, 1900000000000000167, 2099702580669329409, 5, 5, 0, NULL, 1.00, 0, '2026-08-08 12:26:31', '2026-08-08 12:26:31'),
  (1900000000000002168, 1900000000000000175, 2105666932057194497, 5, 5, 1, NULL, 1.00, 0, '2026-07-13 21:39:04', '2026-07-13 21:39:04'),
  (1900000000000002170, 1900000000000000175, 2105667669579415553, 4, 4, 1, NULL, 1.00, 0, '2026-07-17 21:09:23', '2026-07-17 21:09:23'),
  (1900000000000002172, 1900000000000000175, 2105672958714200066, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 14:06:05', '2026-09-26 14:06:05'),
  (1900000000000002173, 1900000000000000175, 2099746243478941698, 4, 4, 1, NULL, 1.00, 0, '2026-06-18 08:46:52', '2026-06-18 08:46:52'),
  (1900000000000002175, 1900000000000000175, 2099723556845113345, 5, 5, 0, '第二次做，莴笋的用量给得刚好，不用自己再摸索，第一次做就很稳。', 1.00, 0, '2026-09-09 07:09:42', '2026-09-09 07:09:42'),
  (1900000000000002177, 1900000000000000175, 2099743322662105089, 5, 5, 1, '第二次做，关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-07-03 14:54:12', '2026-07-03 14:54:12'),
  (1900000000000002178, 1900000000000000175, 2099380565668298753, 5, 5, 1, NULL, 1.00, 0, '2026-09-10 12:11:57', '2026-09-10 12:11:57'),
  (1900000000000002179, 1900000000000000175, 2099431876065607681, 3, 3, 0, '第二次做，可能是我手艺问题，做出来比预期差一点。', 1.00, 0, '2026-08-01 19:49:22', '2026-08-01 19:49:22'),
  (1900000000000002181, 1900000000000000175, 2105677589800534018, 4, 4, 1, NULL, 1.00, 0, '2026-07-06 18:46:25', '2026-07-06 18:46:25'),
  (1900000000000002183, 1900000000000000175, 2100146248997720065, 5, 4, 1, '第二次做，这个做法把莴笋的鲜味全留住了。', 1.00, 0, '2026-09-25 22:41:37', '2026-09-25 22:41:37'),
  (1900000000000002185, 1900000000000000175, 2099723461747658753, 4, 4, 1, NULL, 1.00, 0, '2026-07-27 16:59:26', '2026-07-27 16:59:26'),
  (1900000000000002187, 1900000000000000175, 2099696755372470274, 4, 4, 1, '还原度挺高，要是能标注下中途要不要翻面就更好了。', 1.00, 0, '2026-09-25 20:23:42', '2026-09-25 20:23:42'),
  (1900000000000002189, 1900000000000000175, 2105670358598041602, 4, 4, 1, NULL, 1.00, 0, '2026-07-19 11:35:40', '2026-07-19 11:35:40'),
  (1900000000000002191, 1900000000000000175, 2099749704534716417, 5, 4, 1, '照着方子，做完拍照发朋友圈，好几个人问我要菜谱。', 1.00, 0, '2026-09-22 13:11:40', '2026-09-22 13:11:40'),
  (1900000000000002192, 1900000000000000175, 2100123699110793218, 4, 4, 0, NULL, 1.00, 0, '2026-09-02 19:06:41', '2026-09-02 19:06:41'),
  (1900000000000002194, 1900000000000000175, 2099437330086760449, 5, 4, 0, '今天又做了一次，这道清炒莴笋丝我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-07-26 19:14:42', '2026-07-26 19:14:42'),
  (1900000000000002196, 1900000000000000175, 2099429020906405889, 5, 5, 1, NULL, 1.00, 0, '2026-08-22 11:54:58', '2026-08-22 11:54:58'),
  (1900000000000002197, 1900000000000000175, 2099751660376420354, 3, 3, 0, '食材搭配有点奇怪，我个人不太习惯。', 1.00, 0, '2026-07-03 22:57:39', '2026-07-03 22:57:39'),
  (1900000000000002198, 1900000000000000175, 2099753791607140354, 5, 5, 1, NULL, 1.00, 0, '2026-07-24 13:29:39', '2026-07-24 13:29:39'),
  (1900000000000002200, 1900000000000000175, 2100413312169730049, 5, 5, 1, NULL, 1.00, 0, '2026-09-15 19:52:37', '2026-09-15 19:52:37'),
  (1900000000000002202, 1900000000000000175, 2099753671771680770, 3, 3, 0, NULL, 1.00, 0, '2026-06-28 15:00:53', '2026-06-28 15:00:53'),
  (1900000000000002204, 1900000000000000175, 2099723811162542082, 5, 5, 1, '第二次做，比我想象中简单，重点步骤都点出来了。', 1.00, 0, '2026-08-30 07:17:34', '2026-08-30 07:17:34'),
  (1900000000000002206, 1900000000000000175, 2099756063070220289, 4, 3, 0, NULL, 1.00, 0, '2026-06-24 13:07:02', '2026-06-24 13:07:02'),
  (1900000000000002207, 1900000000000000175, 2099428858867859457, 5, 5, 1, '第二次做，平时不爱吃这个的人都能接受，说明真的不难吃。', 1.00, 0, '2026-07-04 19:20:15', '2026-07-04 19:20:15'),
  (1900000000000002208, 1900000000000000175, 2100442914309070850, 5, 5, 1, '今天又做了一次，味道层次挺清楚，不是一味的重口。', 1.00, 0, '2026-09-01 12:32:51', '2026-09-01 12:32:51'),
  (1900000000000002209, 1900000000000000175, 2099426390394126337, 5, 4, 1, '第一次尝试，调料清单短，厨房小白也不会手忙脚乱。', 1.00, 0, '2026-07-18 18:18:59', '2026-07-18 18:18:59'),
  (1900000000000002211, 1900000000000000175, 2099383437885714434, 3, 4, 0, NULL, 1.00, 0, '2026-08-27 19:35:02', '2026-08-27 19:35:02'),
  (1900000000000002212, 1900000000000000175, 2099746244187779074, 4, 4, 1, NULL, 1.00, 0, '2026-08-09 20:38:07', '2026-08-09 20:38:07'),
  (1900000000000002214, 1900000000000000175, 2105686689317896193, 1, 1, 1, '照着方子，按方子做完全不成形，可能我火候差太远。', 1.00, 0, '2026-09-13 21:07:58', '2026-09-13 21:07:58'),
  (1900000000000002216, 1900000000000000175, 2105687058194350082, 3, 2, 1, NULL, 1.00, 0, '2026-09-02 13:57:18', '2026-09-02 13:57:18'),
  (1900000000000002218, 1900000000000000175, 2105675867279572993, 4, 4, 1, NULL, 1.00, 0, '2026-06-27 14:02:53', '2026-06-27 14:02:53'),
  (1900000000000002220, 1900000000000000175, 2105709470025773057, 4, 4, 1, '上周做的，挺满意的，唯一遗憾是莴笋我没有买到新鲜的。', 1.00, 0, '2026-09-17 17:46:21', '2026-09-17 17:46:21'),
  (1900000000000002221, 1900000000000000175, 2100120517366304770, 4, 4, 1, NULL, 1.00, 0, '2026-08-16 22:52:04', '2026-08-16 22:52:04'),
  (1900000000000002223, 1900000000000000175, 2099751661219475458, 5, 5, 1, NULL, 1.00, 0, '2026-08-23 19:22:30', '2026-08-23 19:22:30'),
  (1900000000000002225, 1900000000000000175, 2105708794130460673, 4, 3, 1, '做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-09-29 21:57:41', '2026-09-29 21:57:41'),
  (1900000000000002258, 1900000000000000180, 2099701719658409986, 2, 2, 1, NULL, 1.00, 0, '2026-05-27 01:44:47', '2026-05-27 01:44:47'),
  (1900000000000002260, 1900000000000000180, 2105677399211360257, 4, 4, 1, '整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-08-01 21:53:22', '2026-08-01 21:53:22'),
  (1900000000000002262, 1900000000000000180, 2105666477310754818, 5, 4, 1, '家里人说比外卖强多了，还干净。', 1.00, 0, '2026-05-04 08:58:04', '2026-05-04 08:58:04'),
  (1900000000000002263, 1900000000000000180, 2105666748212461570, 5, 4, 1, NULL, 1.00, 0, '2026-04-17 05:44:01', '2026-04-17 05:44:01'),
  (1900000000000002265, 1900000000000000180, 2100442919979769857, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 22:14:56', '2026-10-01 22:14:56');
