  (1900000000000002276, 1900000000000000180, 2099697530345631746, 4, 4, 1, '做出来挺香，唯一的问题是油可以再少放一点。', 1.00, 0, '2026-05-02 18:13:46', '2026-05-02 18:13:46'),
  (1900000000000002287, 1900000000000000186, 2099428434026807297, 5, 4, 1, NULL, 1.00, 0, '2026-08-28 06:58:29', '2026-08-28 06:58:29'),
