  (1900000000000002292, 1900000000000000186, 2100123699110793218, 4, 5, 1, NULL, 1.00, 0, '2026-09-13 18:55:29', '2026-09-13 18:55:29'),
  (1900000000000002293, 1900000000000000186, 2100118309295935490, 4, 4, 0, NULL, 1.00, 0, '2026-09-11 18:25:25', '2026-09-11 18:25:25'),
  (1900000000000002295, 1900000000000000186, 2100417387170947073, 4, 4, 1, NULL, 1.00, 0, '2026-08-27 05:32:00', '2026-08-27 05:32:00'),
  (1900000000000002297, 1900000000000000186, 2099751660376420354, 3, 2, 1, '第二次做，没有想象中好，主要是五花肉的味道没出来。', 1.00, 0, '2026-08-24 07:18:09', '2026-08-24 07:18:09'),
  (1900000000000002298, 1900000000000000186, 2099344911148261377, 5, 5, 1, NULL, 1.00, 0, '2026-09-22 19:57:39', '2026-09-22 19:57:39'),
  (1900000000000002299, 1900000000000000186, 2099702594833494018, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 22:47:25', '2026-09-25 22:47:25'),
  (1900000000000002300, 1900000000000000186, 2100442919455481857, 5, 4, 1, '第一次尝试，分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-09-02 23:38:38', '2026-09-02 23:38:38'),
  (1900000000000002301, 1900000000000000186, 2099753167800889345, 4, 4, 1, '味道真不错，就是耗时比写的时间长一些。', 1.00, 0, '2026-09-05 09:36:36', '2026-09-05 09:36:36'),
  (1900000000000002303, 1900000000000000186, 2099723461747658753, 3, 2, 0, NULL, 1.00, 0, '2026-09-25 22:50:55', '2026-09-25 22:50:55'),
  (1900000000000002304, 1900000000000000186, 2099429519441379329, 3, 3, 0, '做法没问题，就是味道偏淡，得自己加重口。', 1.00, 0, '2026-09-28 20:55:54', '2026-09-28 20:55:54'),
  (1900000000000002306, 1900000000000000186, 2099756063070220289, 5, 4, 0, NULL, 1.00, 0, '2026-09-07 19:48:21', '2026-09-07 19:48:21'),
  (1900000000000002308, 1900000000000000186, 2105681892892196865, 3, 3, 1, '一般般，可能这道菜本身就不是我的菜。', 1.00, 0, '2026-09-21 19:24:12', '2026-09-21 19:24:12'),
  (1900000000000002310, 1900000000000000186, 2100442917958115330, 3, 3, 0, NULL, 1.00, 0, '2026-09-27 19:42:23', '2026-09-27 19:42:23'),
  (1900000000000002312, 1900000000000000186, 2099390475495927810, 4, 4, 1, '照着方子，做法没问题，我换了个锅，时间要稍微加几分钟。', 1.00, 0, '2026-09-09 13:29:15', '2026-09-09 13:29:15'),
  (1900000000000002314, 1900000000000000186, 2099752656385208322, 2, 2, 0, NULL, 1.00, 0, '2026-08-24 18:50:35', '2026-08-24 18:50:35'),
  (1900000000000002316, 1900000000000000186, 2099743112946905090, 5, 5, 1, NULL, 1.00, 0, '2026-09-05 11:30:07', '2026-09-05 11:30:07'),
  (1900000000000002318, 1900000000000000186, 2099724470062534657, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 18:41:51', '2026-09-28 18:41:51'),
  (1900000000000002319, 1900000000000000186, 2099743278462529538, 5, 5, 1, NULL, 1.00, 0, '2026-08-25 22:46:08', '2026-08-25 22:46:08'),
  (1900000000000002321, 1900000000000000186, 2105675867279572993, 5, 4, 1, NULL, 1.00, 0, '2026-08-28 12:46:45', '2026-08-28 12:46:45'),
  (1900000000000002322, 1900000000000000186, 2100442913398906882, 5, 5, 1, '第一次尝试，周末做了一锅给爸妈尝，他们说明显比楼下馆子的强。', 1.00, 0, '2026-09-24 19:13:01', '2026-09-24 19:13:01'),
  (1900000000000002324, 1900000000000000186, 2100442919002497026, 5, 5, 1, NULL, 1.00, 0, '2026-08-31 16:24:51', '2026-08-31 16:24:51'),
  (1900000000000002326, 1900000000000000186, 2099698280673062914, 2, 2, 0, '有点失望，味道和想象中差不少。', 1.00, 0, '2026-08-31 07:56:53', '2026-08-31 07:56:53'),
  (1900000000000002328, 1900000000000000186, 2099750963513782274, 5, 5, 1, '按这个量放调料，咸淡刚刚好，不用再补救。', 1.00, 0, '2026-09-19 19:36:16', '2026-09-19 19:36:16'),
  (1900000000000002330, 1900000000000000186, 2100139475368726530, 3, 3, 0, '第一次尝试，不功不过，做完没什么成就感。', 1.00, 0, '2026-08-29 02:14:38', '2026-08-29 02:14:38'),
  (1900000000000002332, 1900000000000000186, 2099383437885714434, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 04:39:13', '2026-10-01 04:39:13'),
