  (1900000000000002400, 1900000000000000194, 2099752563540094978, 2, 2, 0, '照着方子，食材用量不太合理，我按量做出来太多了。', 1.00, 0, '2026-09-20 20:17:52', '2026-09-20 20:17:52'),
  (1900000000000002401, 1900000000000000194, 2099723556845113345, 4, 4, 1, NULL, 1.00, 0, '2026-08-24 23:40:18', '2026-08-24 23:40:18'),
