  (1900000000000002515, 1900000000000000210, 2099794921763409921, 5, 5, 1, '收汁那一步别省，做出来味道完全不一样，香得很。', 1.00, 0, '2026-09-20 11:03:21', '2026-09-20 11:03:21'),
  (1900000000000002516, 1900000000000000210, 2099701394633404418, 4, 4, 0, NULL, 1.00, 0, '2026-09-18 11:27:23', '2026-09-18 11:27:23'),
  (1900000000000002518, 1900000000000000210, 2099428168997126145, 5, 5, 1, '火候说得很明白，跟着时间走不会老。', 1.00, 0, '2026-09-19 13:58:19', '2026-09-19 13:58:19'),
  (1900000000000002519, 1900000000000000210, 2099383042388013057, 5, 5, 1, '家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-28 18:01:46', '2026-09-28 18:01:46'),
  (1900000000000002520, 1900000000000000210, 2100146248997720065, 4, 5, 1, '照着方子，味道可以，下次我想试试加香菜提味。', 1.00, 0, '2026-09-16 20:25:38', '2026-09-16 20:25:38'),
  (1900000000000002521, 1900000000000000210, 2099379216679469057, 4, 3, 1, '整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-09-12 18:03:21', '2026-09-12 18:03:21'),
  (1900000000000002523, 1900000000000000210, 2100413312169730049, 5, 5, 1, '第二次做，这道糖醋排骨我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-09-14 19:06:51', '2026-09-14 19:06:51'),
  (1900000000000002525, 1900000000000000210, 2100442913398906882, 4, 4, 1, NULL, 1.00, 0, '2026-09-26 16:01:26', '2026-09-26 16:01:26'),
