  (1900000000000002555, 1900000000000000210, 2099755347190607873, 4, 5, 1, '蛮好吃的，就是分量偏少，两个人吃略紧。', 1.00, 0, '2026-09-18 13:04:24', '2026-09-18 13:04:24'),
  (1900000000000002557, 1900000000000000210, 2099433596644569090, 4, 3, 1, NULL, 1.00, 0, '2026-09-17 16:04:25', '2026-09-17 16:04:25'),
