  (1900000000000002699, 1900000000000000232, 2099743185026019329, 3, 2, 0, '不功不过，做完没什么成就感。', 1.00, 0, '2026-09-14 17:47:29', '2026-09-14 17:47:29'),
  (1900000000000002700, 1900000000000000232, 2100442917568045058, 5, 4, 1, '孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-06-07 12:08:27', '2026-06-07 12:08:27'),
  (1900000000000002702, 1900000000000000232, 2099697354612682754, 4, 4, 1, '照着方子，还原度挺高，要是能标注下中途要不要翻面就更好了。', 1.00, 0, '2026-08-13 11:58:42', '2026-08-13 11:58:42'),
