  (1900000000000002791, 1900000000000000240, 2105670358598041602, 5, 5, 1, '虾仁处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-09-03 02:01:55', '2026-09-03 02:01:55'),
  (1900000000000002793, 1900000000000000240, 2100442919002497026, 4, 4, 1, NULL, 1.00, 0, '2026-09-27 12:42:18', '2026-09-27 12:42:18'),
  (1900000000000002795, 1900000000000000240, 2099429020906405889, 5, 4, 1, '照着方子，以前在外面吃过，自己照着做居然还原了八九成。', 1.00, 0, '2026-08-20 05:30:12', '2026-08-20 05:30:12'),
  (1900000000000002797, 1900000000000000240, 2099335487637712897, 5, 5, 0, '照着方子，关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-09-25 11:21:31', '2026-09-25 11:21:31'),
  (1900000000000002799, 1900000000000000240, 2099752563540094978, 4, 4, 1, '第二次做，做法没问题，我换了个锅，时间要稍微加几分钟。', 1.00, 0, '2026-05-30 23:10:59', '2026-05-30 23:10:59'),
  (1900000000000002800, 1900000000000000240, 2105707494147858434, 5, 5, 1, NULL, 1.00, 0, '2026-09-14 17:05:09', '2026-09-14 17:05:09'),
  (1900000000000002823, 1900000000000000248, 2100135297292488705, 5, 4, 0, '今天又做了一次，冷藏后再热一遍，味道居然更进去了。', 1.00, 0, '2026-06-23 09:37:59', '2026-06-23 09:37:59'),
  (1900000000000002824, 1900000000000000248, 2099701394633404418, 4, 4, 1, NULL, 1.00, 0, '2026-06-20 17:27:35', '2026-06-20 17:27:35'),
