  (1900000000000002917, 1900000000000000256, 2105666523875917825, 4, 5, 1, '做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-07-26 13:01:07', '2026-07-26 13:01:07'),
  (1900000000000002919, 1900000000000000256, 2099437330086760449, 3, 2, 0, NULL, 1.00, 0, '2026-09-02 18:21:43', '2026-09-02 18:21:43'),
  (1900000000000002921, 1900000000000000256, 2099707719815823361, 4, 4, 0, '成功了，感谢。下次试试加别的配菜。', 1.00, 0, '2026-09-28 21:23:52', '2026-09-28 21:23:52'),
  (1900000000000002922, 1900000000000000256, 2100119371360817154, 4, 5, 1, '挺满意的，唯一遗憾是鸡胸肉我没有买到新鲜的。', 1.00, 0, '2026-08-06 19:37:33', '2026-08-06 19:37:33'),
  (1900000000000002923, 1900000000000000256, 2100413312169730049, 5, 5, 1, '今天又做了一次，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-09-14 19:29:03', '2026-09-14 19:29:03'),
  (1900000000000002924, 1900000000000000256, 2105681488087334913, 3, 4, 0, '味道一般，没什么惊艳的，但也算能吃。', 1.00, 0, '2026-08-26 21:55:00', '2026-08-26 21:55:00'),
