  (1900000000000003020, 1900000000000000272, 2100139475368726530, 4, 4, 1, '第一次尝试，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-08-19 15:13:16', '2026-08-19 15:13:16'),
  (1900000000000003022, 1900000000000000272, 2099428168997126145, 5, 5, 0, '照着方子，出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-08-20 11:03:35', '2026-08-20 11:03:35'),
  (1900000000000003024, 1900000000000000272, 2099755611784081409, 5, 5, 1, NULL, 1.00, 0, '2026-09-23 21:08:25', '2026-09-23 21:08:25'),
  (1900000000000003025, 1900000000000000272, 2100146248997720065, 4, 5, 1, NULL, 1.00, 0, '2026-07-27 09:09:40', '2026-07-27 09:09:40'),
  (1900000000000003027, 1900000000000000272, 2105682083112271873, 1, 1, 1, NULL, 1.00, 0, '2026-06-30 16:16:55', '2026-06-30 16:16:55'),
  (1900000000000003028, 1900000000000000272, 2105670358598041602, 4, 3, 1, '上周做的，还原度挺高，要是能标注下中途要不要翻面就更好了。', 1.00, 0, '2026-09-13 10:51:26', '2026-09-13 10:51:26'),
  (1900000000000003029, 1900000000000000272, 2099751661219475458, 4, 4, 0, NULL, 1.00, 0, '2026-08-07 17:27:34', '2026-08-07 17:27:34'),
  (1900000000000003031, 1900000000000000272, 2100139042453639170, 5, 4, 1, NULL, 1.00, 0, '2026-07-19 10:35:34', '2026-07-19 10:35:34'),
  (1900000000000003033, 1900000000000000272, 2099705010635157506, 5, 4, 1, '步骤写得清楚，我这种平时不进厨房的人也一次成功了。', 1.00, 0, '2026-08-18 19:12:36', '2026-08-18 19:12:36'),
  (1900000000000003034, 1900000000000000272, 2105666477310754818, 4, 4, 1, NULL, 1.00, 0, '2026-06-22 17:03:11', '2026-06-22 17:03:11'),
  (1900000000000003036, 1900000000000000272, 2105672501321154561, 5, 4, 1, '今天又做了一次，按这个量放调料，咸淡刚刚好，不用再补救。', 1.00, 0, '2026-09-13 21:09:02', '2026-09-13 21:09:02'),
  (1900000000000003038, 1900000000000000272, 2105709121059680258, 5, 5, 1, '第二次做，第一次做就成功了，很有成就感。', 1.00, 0, '2026-09-10 21:54:14', '2026-09-10 21:54:14'),
  (1900000000000003040, 1900000000000000272, 2099794921763409921, 3, 3, 0, '第一次尝试，感觉少了点什么，我自己加了点调料才好吃。', 1.00, 0, '2026-07-25 20:53:31', '2026-07-25 20:53:31'),
  (1900000000000003042, 1900000000000000272, 2105681825976270849, 2, 2, 0, '今天又做了一次，步骤里的时间不太准，我按着做有点糊了。', 1.00, 0, '2026-07-07 16:52:17', '2026-07-07 16:52:17'),
  (1900000000000003044, 1900000000000000272, 2105687058194350082, 5, 5, 1, NULL, 1.00, 0, '2026-07-01 18:11:48', '2026-07-01 18:11:48'),
  (1900000000000003046, 1900000000000000272, 2100442919455481857, 5, 5, 0, NULL, 1.00, 0, '2026-09-24 21:31:27', '2026-09-24 21:31:27'),
  (1900000000000003048, 1900000000000000272, 2099428007537393665, 5, 5, 1, NULL, 1.00, 0, '2026-07-03 18:24:13', '2026-07-03 18:24:13'),
  (1900000000000003050, 1900000000000000272, 2100442917958115330, 4, 3, 1, '满意，就是这个量我家三口人吃有点不够。', 1.00, 0, '2026-08-04 08:15:16', '2026-08-04 08:15:16'),
  (1900000000000003052, 1900000000000000272, 2099698692641796098, 5, 5, 1, NULL, 1.00, 0, '2026-09-20 20:53:20', '2026-09-20 20:53:20'),
  (1900000000000003054, 1900000000000000272, 2099701393857458177, 4, 4, 1, NULL, 1.00, 0, '2026-08-04 12:55:52', '2026-08-04 12:55:52'),
  (1900000000000003056, 1900000000000000272, 2099707576462901250, 4, 4, 1, NULL, 1.00, 0, '2026-07-24 17:44:27', '2026-07-24 17:44:27'),
  (1900000000000003058, 1900000000000000272, 2099427479453548545, 5, 4, 1, '上周做的，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-07-16 20:22:16', '2026-07-16 20:22:16'),
  (1900000000000003059, 1900000000000000272, 2099707719815823361, 5, 5, 1, NULL, 1.00, 0, '2026-08-14 03:48:56', '2026-08-14 03:48:56'),
  (1900000000000003061, 1900000000000000272, 2099701634144940033, 5, 5, 1, NULL, 1.00, 0, '2026-05-31 15:53:18', '2026-05-31 15:53:18'),
  (1900000000000003063, 1900000000000000272, 2099428858867859457, 5, 5, 1, NULL, 1.00, 0, '2026-07-09 06:26:44', '2026-07-09 06:26:44'),
  (1900000000000003064, 1900000000000000272, 2099746244187779074, 2, 2, 0, '今天又做了一次，做出来口感偏老，下次不会按这个时间来。', 1.00, 0, '2026-07-02 17:09:32', '2026-07-02 17:09:32'),
  (1900000000000003065, 1900000000000000272, 2105667669579415553, 2, 2, 0, '食材用量不太合理，我按量做出来太多了。', 1.00, 0, '2026-07-24 17:02:16', '2026-07-24 17:02:16'),
  (1900000000000003067, 1900000000000000272, 2099428764521185282, 5, 4, 1, NULL, 1.00, 0, '2026-08-11 18:02:27', '2026-08-11 18:02:27'),
  (1900000000000003068, 1900000000000000272, 2099724074103459842, 5, 5, 1, NULL, 1.00, 0, '2026-06-13 11:31:31', '2026-06-13 11:31:31'),
  (1900000000000003070, 1900000000000000272, 2099697410912825345, 4, 4, 1, NULL, 1.00, 0, '2026-08-04 11:52:41', '2026-08-04 11:52:41'),
