  (1900000000000003491, 1900000000000000317, 2099752563540094978, 4, 4, 1, NULL, 1.00, 0, '2026-09-27 10:35:52', '2026-09-27 10:35:52'),
  (1900000000000003493, 1900000000000000317, 2099379216679469057, 2, 1, 0, '味道比较寡淡，需要自己大改，不太推荐照搬。', 1.00, 0, '2026-09-24 21:40:04', '2026-09-24 21:40:04'),
  (1900000000000003495, 1900000000000000317, 2099755579194339330, 5, 5, 1, '今天又做了一次，调料清单短，厨房小白也不会手忙脚乱。', 1.00, 0, '2026-09-25 23:02:35', '2026-09-25 23:02:35'),
  (1900000000000003496, 1900000000000000317, 2099755611784081409, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 08:35:54', '2026-09-26 08:35:54'),
  (1900000000000003497, 1900000000000000317, 2100139042453639170, 5, 5, 1, '收汁那一步别省，做出来味道完全不一样，香得很。', 1.00, 0, '2026-10-01 09:28:59', '2026-10-01 09:28:59'),
  (1900000000000003498, 1900000000000000317, 2099433596644569090, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 19:10:59', '2026-09-26 19:10:59'),
  (1900000000000003499, 1900000000000000317, 2105681488087334913, 4, 4, 1, NULL, 1.00, 0, '2026-09-24 16:39:22', '2026-09-24 16:39:22'),
  (1900000000000003500, 1900000000000000317, 2099743185026019329, 4, 3, 1, NULL, 1.00, 0, '2026-09-25 09:21:10', '2026-09-25 09:21:10'),
  (1900000000000003502, 1900000000000000317, 2099724431911145474, 2, 3, 0, NULL, 1.00, 0, '2026-09-28 08:46:38', '2026-09-28 08:46:38'),
  (1900000000000003504, 1900000000000000317, 2099697355321520129, 4, 3, 1, NULL, 1.00, 0, '2026-09-29 16:36:38', '2026-09-29 16:36:38'),
  (1900000000000003506, 1900000000000000317, 2105707611408015361, 5, 5, 1, NULL, 1.00, 0, '2026-09-29 12:32:38', '2026-09-29 12:32:38'),
  (1900000000000003508, 1900000000000000317, 2099753672547627009, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 09:38:38', '2026-09-25 09:38:38'),
  (1900000000000003510, 1900000000000000317, 2100442918482403330, 3, 3, 0, '做法没问题，就是味道偏淡，得自己加重口。', 1.00, 0, '2026-09-23 18:12:49', '2026-09-23 18:12:49'),
  (1900000000000003512, 1900000000000000317, 2100123699110793218, 5, 4, 1, '排骨处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-09-26 12:52:18', '2026-09-26 12:52:18'),
  (1900000000000003513, 1900000000000000317, 2100406228522950657, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 21:30:18', '2026-10-01 21:30:18'),
  (1900000000000003514, 1900000000000000317, 2100119371360817154, 5, 5, 0, NULL, 1.00, 0, '2026-10-01 20:12:53', '2026-10-01 20:12:53'),
  (1900000000000003515, 1900000000000000317, 2099723556845113345, 3, 3, 0, '做出来了，家里人反应平平，可能不合我们口味。', 1.00, 0, '2026-09-22 06:51:38', '2026-09-22 06:51:38'),
  (1900000000000003516, 1900000000000000317, 2099701394633404418, 4, 3, 0, '上周做的，整体不错，唯一是步骤里水量说得有点模糊。', 1.00, 0, '2026-09-30 00:11:19', '2026-09-30 00:11:19'),
  (1900000000000003518, 1900000000000000317, 2099751661219475458, 5, 5, 1, '今天又做了一次，一人份的量刚好，不会做多做少。', 1.00, 0, '2026-09-25 13:38:19', '2026-09-25 13:38:19'),
  (1900000000000003520, 1900000000000000317, 2105683168786890753, 4, 5, 1, NULL, 1.00, 0, '2026-09-26 12:57:13', '2026-09-26 12:57:13'),
  (1900000000000003521, 1900000000000000317, 2100442912098672641, 4, 4, 1, NULL, 1.00, 0, '2026-09-27 15:23:33', '2026-09-27 15:23:33'),
  (1900000000000003539, 1900000000000000323, 2100442917110865922, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 14:58:03', '2026-09-26 14:58:03'),
  (1900000000000003541, 1900000000000000323, 2100412643312459778, 5, 5, 0, NULL, 1.00, 0, '2026-10-01 23:32:29', '2026-10-01 23:32:29'),
