  (1900000000000003549, 1900000000000000323, 2099383437885714434, 5, 5, 1, NULL, 1.00, 0, '2026-09-27 21:20:04', '2026-09-27 21:20:04'),
  (1900000000000003551, 1900000000000000323, 2099433163855310849, 5, 5, 1, NULL, 1.00, 0, '2026-09-29 19:11:06', '2026-09-29 19:11:06'),
  (1900000000000003553, 1900000000000000323, 2099431876065607681, 4, 5, 1, NULL, 1.00, 0, '2026-09-30 14:04:13', '2026-09-30 14:04:13'),
  (1900000000000003555, 1900000000000000323, 2099697410912825345, 3, 4, 1, NULL, 1.00, 0, '2026-10-01 20:10:00', '2026-10-01 20:10:00'),
  (1900000000000003556, 1900000000000000323, 2100122576090091521, 4, 3, 1, NULL, 1.00, 0, '2026-09-28 08:34:36', '2026-09-28 08:34:36'),
  (1900000000000003558, 1900000000000000323, 2105687058194350082, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 20:02:12', '2026-10-01 20:02:12'),
  (1900000000000003560, 1900000000000000323, 2099750964285534210, 4, 3, 1, '整体不错，唯一是步骤里水量说得有点模糊。', 1.00, 0, '2026-10-01 20:09:23', '2026-10-01 20:09:23'),
  (1900000000000003562, 1900000000000000323, 2105682083112271873, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 20:12:44', '2026-10-01 20:12:44'),
  (1900000000000003564, 1900000000000000323, 2099756277965385729, 2, 3, 0, NULL, 1.00, 0, '2026-09-30 18:51:23', '2026-09-30 18:51:23'),
  (1900000000000003575, 1900000000000000327, 2099724470062534657, 5, 5, 1, '上周做的，分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-09-29 07:53:58', '2026-09-29 07:53:58'),
  (1900000000000003576, 1900000000000000327, 2099699301033979906, 5, 5, 0, '连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-09-30 07:33:09', '2026-09-30 07:33:09'),
  (1900000000000003578, 1900000000000000327, 2100406228522950657, 5, 5, 1, '做完拍照发朋友圈，好几个人问我要菜谱。', 1.00, 0, '2026-09-25 16:49:52', '2026-09-25 16:49:52'),
  (1900000000000003580, 1900000000000000327, 2105667671450075137, 3, 3, 0, '不功不过，做完没什么成就感。', 1.00, 0, '2026-09-26 16:39:45', '2026-09-26 16:39:45'),
  (1900000000000003581, 1900000000000000327, 2099701635050909697, 4, 4, 1, NULL, 1.00, 0, '2026-09-30 13:16:42', '2026-09-30 13:16:42'),
  (1900000000000003582, 1900000000000000327, 2100442913013030913, 4, 5, 1, NULL, 1.00, 0, '2026-09-25 03:14:42', '2026-09-25 03:14:42'),
  (1900000000000003583, 1900000000000000327, 2105707611408015361, 4, 3, 0, NULL, 1.00, 0, '2026-10-01 19:04:01', '2026-10-01 19:04:01');
INSERT INTO t_dish_rating (id, dish_id, user_id, score, taste_score, cooked_flag, comment, weight, deleted, create_time, update_time) VALUES
  (1900000000000003584, 1900000000000000327, 2100442917958115330, 3, 3, 0, NULL, 1.00, 0, '2026-09-24 20:22:25', '2026-09-24 20:22:25'),
  (1900000000000003585, 1900000000000000327, 2100145795866087425, 4, 4, 1, '整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-09-27 23:13:51', '2026-09-27 23:13:51'),
  (1900000000000003586, 1900000000000000327, 2099723556845113345, 3, 4, 1, NULL, 1.00, 0, '2026-09-26 23:01:47', '2026-09-26 23:01:47'),
  (1900000000000003588, 1900000000000000327, 2100140070104256514, 4, 4, 1, NULL, 1.00, 0, '2026-10-01 19:27:26', '2026-10-01 19:27:26'),
  (1900000000000003589, 1900000000000000327, 2105685510701694978, 5, 5, 1, '上周做的，孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-09-27 19:32:34', '2026-09-27 19:32:34'),
  (1900000000000003590, 1900000000000000327, 2100442912622960641, 5, 5, 0, NULL, 1.00, 0, '2026-10-01 20:53:20', '2026-10-01 20:53:20'),
  (1900000000000003592, 1900000000000000327, 2099681025193185281, 5, 5, 1, '配米饭配面条都行，怎么搭都不出错。', 1.00, 0, '2026-09-26 17:11:12', '2026-09-26 17:11:12'),
  (1900000000000003593, 1900000000000000327, 2099380565668298753, 5, 5, 1, '味道很正，清甜的香气一进门就闻到了。', 1.00, 0, '2026-09-28 08:36:47', '2026-09-28 08:36:47'),
  (1900000000000003595, 1900000000000000327, 2100442917568045058, 5, 5, 1, '照着方子，这道山药排骨汤我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-09-29 23:08:38', '2026-09-29 23:08:38'),
  (1900000000000003597, 1900000000000000327, 2100415018777501697, 5, 5, 1, NULL, 1.00, 0, '2026-09-23 15:22:02', '2026-09-23 15:22:02'),
  (1900000000000003599, 1900000000000000327, 2099426804636172290, 5, 5, 1, '照着方子，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-09-27 10:41:19', '2026-09-27 10:41:19'),
  (1900000000000003601, 1900000000000000327, 2099437330086760449, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 10:47:00', '2026-09-25 10:47:00'),
  (1900000000000003603, 1900000000000000327, 2105666569564471297, 5, 4, 1, '今天又做了一次，以前在外面吃过，自己照着做居然还原了八九成。', 1.00, 0, '2026-09-26 10:52:08', '2026-09-26 10:52:08'),
  (1900000000000003604, 1900000000000000327, 2100417387170947073, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 12:48:53', '2026-09-26 12:48:53'),
  (1900000000000003605, 1900000000000000327, 2099433596644569090, 5, 5, 1, NULL, 1.00, 0, '2026-09-29 12:16:41', '2026-09-29 12:16:41'),
  (1900000000000003607, 1900000000000000327, 2100442914309070850, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 09:53:13', '2026-09-28 09:53:13'),
  (1900000000000003609, 1900000000000000327, 2105682187139399682, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 19:04:57', '2026-09-26 19:04:57'),
  (1900000000000003610, 1900000000000000327, 2105666571758092290, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 19:05:48', '2026-09-28 19:05:48'),
  (1900000000000003612, 1900000000000000327, 2105675867279572993, 3, 3, 1, '今天又做了一次，一般般，可能这道菜本身就不是我的菜。', 1.00, 0, '2026-09-29 08:00:37', '2026-09-29 08:00:37'),
  (1900000000000003614, 1900000000000000327, 2100442919002497026, 4, 5, 0, NULL, 1.00, 0, '2026-09-24 04:43:18', '2026-09-24 04:43:18'),
  (1900000000000003615, 1900000000000000327, 2099681709128970242, 1, 1, 0, NULL, 1.00, 0, '2026-09-25 13:43:41', '2026-09-25 13:43:41'),
  (1900000000000003617, 1900000000000000327, 2099698692641796098, 4, 5, 1, NULL, 1.00, 0, '2026-09-27 20:10:10', '2026-09-27 20:10:10'),
  (1900000000000003619, 1900000000000000327, 2105709796896272386, 5, 4, 1, NULL, 1.00, 0, '2026-09-28 17:10:59', '2026-09-28 17:10:59'),
  (1900000000000003621, 1900000000000000327, 2099701705271947265, 4, 3, 1, NULL, 1.00, 0, '2026-09-29 22:38:40', '2026-09-29 22:38:40'),
  (1900000000000003623, 1900000000000000327, 2100442916662075394, 4, 4, 1, NULL, 1.00, 0, '2026-09-29 08:28:04', '2026-09-29 08:28:04'),
  (1900000000000003625, 1900000000000000327, 2099702580669329409, 2, 2, 1, '第二次做，步骤里的时间不太准，我按着做有点糊了。', 1.00, 0, '2026-09-27 17:38:36', '2026-09-27 17:38:36'),
  (1900000000000003627, 1900000000000000327, 2099752656385208322, 4, 4, 1, '挺好，就是调料里有一样我家没有，用别的代替了。', 1.00, 0, '2026-10-01 20:54:59', '2026-10-01 20:54:59'),
  (1900000000000003628, 1900000000000000327, 2099697354612682754, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 16:19:44', '2026-10-01 16:19:44'),
  (1900000000000003629, 1900000000000000327, 2105677399211360257, 5, 5, 1, NULL, 1.00, 0, '2026-09-26 19:46:11', '2026-09-26 19:46:11'),
  (1900000000000003631, 1900000000000000327, 2099750963513782274, 5, 5, 1, '照着方子，出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-09-27 20:44:42', '2026-09-27 20:44:42'),
  (1900000000000003633, 1900000000000000327, 2105682212728848385, 4, 3, 1, '第一次尝试，成功了，就是最后收汁有点久，稍微干了一点。', 1.00, 0, '2026-09-29 18:23:51', '2026-09-29 18:23:51'),
  (1900000000000003635, 1900000000000000327, 2099429064401338370, 5, 5, 1, NULL, 1.00, 0, '2026-09-25 23:14:57', '2026-09-25 23:14:57'),
  (1900000000000003637, 1900000000000000327, 2105687200876183554, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 13:10:41', '2026-09-28 13:10:41'),
  (1900000000000003639, 1900000000000000327, 2099383579003072514, 5, 5, 0, NULL, 1.00, 0, '2026-09-25 20:59:07', '2026-09-25 20:59:07'),
  (1900000000000003641, 1900000000000000327, 2099794921763409921, 4, 4, 1, NULL, 1.00, 0, '2026-10-01 13:31:59', '2026-10-01 13:31:59'),
  (1900000000000003642, 1900000000000000327, 2100121454612893698, 4, 3, 1, NULL, 1.00, 0, '2026-09-30 18:42:22', '2026-09-30 18:42:22'),
  (1900000000000003644, 1900000000000000327, 2099701719658409986, 3, 2, 1, NULL, 1.00, 0, '2026-09-29 18:38:24', '2026-09-29 18:38:24'),
  (1900000000000003645, 1900000000000000327, 2105686689317896193, 5, 5, 1, '孩子平时挑食，这次居然添了半碗饭。', 1.00, 0, '2026-10-01 21:56:28', '2026-10-01 21:56:28'),
  (1900000000000003646, 1900000000000000327, 2099755611784081409, 2, 3, 1, NULL, 1.00, 0, '2026-09-26 11:17:26', '2026-09-26 11:17:26'),
  (1900000000000003648, 1900000000000000327, 2099428168997126145, 5, 5, 1, NULL, 1.00, 0, '2026-09-27 15:59:25', '2026-09-27 15:59:25'),
  (1900000000000003673, 1900000000000000334, 2099724074103459842, 3, 2, 0, '食材搭配有点奇怪，我个人不太习惯。', 1.00, 0, '2026-08-13 17:17:36', '2026-08-13 17:17:36'),
  (1900000000000003674, 1900000000000000334, 2099344911148261377, 4, 4, 1, NULL, 1.00, 0, '2026-07-03 20:22:30', '2026-07-03 20:22:30'),
  (1900000000000003675, 1900000000000000334, 2105672958714200066, 5, 5, 1, '今天又做了一次，做完拍照发朋友圈，好几个人问我要菜谱。', 1.00, 0, '2026-09-16 18:40:10', '2026-09-16 18:40:10'),
  (1900000000000003676, 1900000000000000334, 2105709470025773057, 1, 1, 0, NULL, 1.00, 0, '2026-08-07 19:11:11', '2026-08-07 19:11:11'),
  (1900000000000003678, 1900000000000000334, 2099705547174719489, 4, 4, 1, NULL, 1.00, 0, '2026-06-20 19:50:42', '2026-06-20 19:50:42'),
  (1900000000000003680, 1900000000000000334, 2099743278462529538, 5, 5, 1, '火候说得很明白，跟着时间走不会老。', 1.00, 0, '2026-08-03 18:14:46', '2026-08-03 18:14:46'),
  (1900000000000003682, 1900000000000000334, 2100123699110793218, 5, 5, 0, NULL, 1.00, 0, '2026-09-05 21:31:59', '2026-09-05 21:31:59'),
  (1900000000000003683, 1900000000000000334, 2100442915294732290, 4, 4, 1, NULL, 1.00, 0, '2026-07-25 17:53:38', '2026-07-25 17:53:38'),
  (1900000000000003685, 1900000000000000334, 2100442912098672641, 5, 4, 0, '今天又做了一次，第二次做了，把清淡的味道调得更足一点，更合家人口味。', 1.00, 0, '2026-07-21 17:40:55', '2026-07-21 17:40:55'),
  (1900000000000003686, 1900000000000000334, 2099681709128970242, 4, 5, 1, '步骤很清楚，新手也能做，只是备料比我预想的花时间。', 1.00, 0, '2026-06-23 18:02:04', '2026-06-23 18:02:04'),
  (1900000000000003688, 1900000000000000334, 2100442915739328514, 4, 4, 1, NULL, 1.00, 0, '2026-09-27 12:22:20', '2026-09-27 12:22:20'),
  (1900000000000003689, 1900000000000000334, 2099765319706210306, 4, 3, 1, NULL, 1.00, 0, '2026-09-23 17:59:07', '2026-09-23 17:59:07'),
  (1900000000000003690, 1900000000000000334, 2105667474145820673, 5, 5, 1, '第二次做，已经加入我的常做清单，隔几天就要做一次。', 1.00, 0, '2026-06-18 19:01:45', '2026-06-18 19:01:45'),
  (1900000000000003692, 1900000000000000334, 2100442914833358849, 5, 4, 1, NULL, 1.00, 0, '2026-07-21 23:50:47', '2026-07-21 23:50:47'),
  (1900000000000003693, 1900000000000000334, 2099751786742411265, 5, 4, 1, NULL, 1.00, 0, '2026-08-09 16:15:13', '2026-08-09 16:15:13'),
  (1900000000000003695, 1900000000000000334, 2100442914309070850, 4, 5, 1, NULL, 1.00, 0, '2026-08-10 12:10:45', '2026-08-10 12:10:45'),
  (1900000000000003697, 1900000000000000334, 2100413312169730049, 5, 5, 1, '关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-09-13 11:35:57', '2026-09-13 11:35:57'),
  (1900000000000003699, 1900000000000000334, 2105708794130460673, 5, 5, 1, NULL, 1.00, 0, '2026-08-29 16:55:24', '2026-08-29 16:55:24'),
  (1900000000000003700, 1900000000000000334, 2105682212728848385, 5, 5, 1, NULL, 1.00, 0, '2026-08-11 12:30:28', '2026-08-11 12:30:28'),
  (1900000000000003701, 1900000000000000334, 2105681825976270849, 4, 4, 1, NULL, 1.00, 0, '2026-09-21 01:28:16', '2026-09-21 01:28:16'),
  (1900000000000003703, 1900000000000000334, 2100139475368726530, 4, 4, 1, '挺满意的，唯一遗憾是海带我没有买到新鲜的。', 1.00, 0, '2026-06-21 18:16:10', '2026-06-21 18:16:10'),
  (1900000000000003705, 1900000000000000334, 2105681892892196865, 3, 4, 1, NULL, 1.00, 0, '2026-07-17 14:41:39', '2026-07-17 14:41:39'),
