  (1900000000000004684, 1900000000000000455, 2100118309295935490, 4, 4, 1, NULL, 1.00, 0, '2026-09-03 13:41:26', '2026-09-03 13:41:26'),
  (1900000000000004685, 1900000000000000455, 2099749704534716417, 5, 5, 0, NULL, 1.00, 0, '2026-08-26 14:16:11', '2026-08-26 14:16:11'),
  (1900000000000004687, 1900000000000000455, 2099426141265051649, 3, 2, 0, NULL, 1.00, 0, '2026-08-06 18:57:36', '2026-08-06 18:57:36'),
  (1900000000000004689, 1900000000000000455, 2099681025193185281, 3, 3, 0, NULL, 1.00, 0, '2026-09-24 18:37:18', '2026-09-24 18:37:18'),
  (1900000000000004691, 1900000000000000455, 2099705547174719489, 4, 4, 0, '照着方子，挺满意的，唯一遗憾是黄瓜我没有买到新鲜的。', 1.00, 0, '2026-08-12 19:56:44', '2026-08-12 19:56:44'),
  (1900000000000004692, 1900000000000000455, 2099707576462901250, 4, 4, 1, NULL, 1.00, 0, '2026-09-08 19:49:23', '2026-09-08 19:49:23'),
  (1900000000000004694, 1900000000000000455, 2099753790629867522, 4, 4, 1, '第二次做，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-08-13 05:48:47', '2026-08-13 05:48:47'),
  (1900000000000004695, 1900000000000000455, 2105707611408015361, 4, 4, 1, NULL, 1.00, 0, '2026-07-11 06:00:09', '2026-07-11 06:00:09'),
  (1900000000000004696, 1900000000000000455, 2099437330086760449, 5, 5, 1, NULL, 1.00, 0, '2026-09-23 14:31:57', '2026-09-23 14:31:57'),
  (1900000000000004697, 1900000000000000455, 2100120517366304770, 2, 2, 1, NULL, 1.00, 0, '2026-09-08 18:40:47', '2026-09-08 18:40:47'),
  (1900000000000004699, 1900000000000000455, 2099749705306468354, 5, 5, 1, NULL, 1.00, 0, '2026-09-15 19:26:13', '2026-09-15 19:26:13'),
  (1900000000000004701, 1900000000000000455, 2100140070104256514, 4, 4, 1, NULL, 1.00, 0, '2026-09-03 18:08:31', '2026-09-03 18:08:31'),
  (1900000000000004703, 1900000000000000455, 2099431876065607681, 4, 3, 1, '味道不错，就是黄瓜可以再多一点，吃着不过瘾。', 1.00, 0, '2026-07-28 17:54:48', '2026-07-28 17:54:48'),
  (1900000000000004705, 1900000000000000455, 2099707575057809409, 5, 5, 1, NULL, 1.00, 0, '2026-07-07 19:11:10', '2026-07-07 19:11:10'),
  (1900000000000004707, 1900000000000000455, 2105666523875917825, 4, 4, 1, '照着方子，味道可以，就是火候不太好掌握，我第一次稍微过了。', 1.00, 0, '2026-08-09 15:50:49', '2026-08-09 15:50:49'),
  (1900000000000004709, 1900000000000000455, 2099427252554285058, 5, 5, 0, NULL, 1.00, 0, '2026-09-04 19:29:37', '2026-09-04 19:29:37'),
  (1900000000000004710, 1900000000000000455, 2100122576090091521, 3, 3, 1, NULL, 1.00, 0, '2026-08-20 18:34:08', '2026-08-20 18:34:08'),
  (1900000000000004711, 1900000000000000455, 2105685384474116098, 1, 1, 0, '今天又做了一次，咸得没法入口，建议把用量再核一下。', 1.00, 0, '2026-09-16 18:46:54', '2026-09-16 18:46:54'),
  (1900000000000004713, 1900000000000000455, 2100442915294732290, 5, 5, 1, NULL, 1.00, 0, '2026-08-15 20:42:02', '2026-08-15 20:42:02'),
  (1900000000000004714, 1900000000000000455, 2099755611784081409, 5, 4, 1, '真的省事，洗的锅碗都比其他菜少。', 1.00, 0, '2026-06-22 19:15:13', '2026-06-22 19:15:13'),
  (1900000000000004715, 1900000000000000455, 2099756063070220289, 5, 4, 1, '第一次尝试，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-09-25 18:14:37', '2026-09-25 18:14:37'),
  (1900000000000004717, 1900000000000000455, 2105666930429804546, 3, 3, 1, '第一次尝试，做出来了，家里人反应平平，可能不合我们口味。', 1.00, 0, '2026-09-03 13:18:47', '2026-09-03 13:18:47'),
  (1900000000000004718, 1900000000000000455, 2099433163855310849, 5, 5, 1, '照着方子，平时不爱吃这个的人都能接受，说明真的不难吃。', 1.00, 0, '2026-06-24 19:06:23', '2026-06-24 19:06:23'),
  (1900000000000004719, 1900000000000000455, 2099743185026019329, 5, 5, 1, NULL, 1.00, 0, '2026-09-21 08:32:42', '2026-09-21 08:32:42'),
  (1900000000000004721, 1900000000000000455, 2100442919002497026, 5, 5, 1, NULL, 1.00, 0, '2026-08-19 19:33:20', '2026-08-19 19:33:20'),
  (1900000000000004723, 1900000000000000455, 2099383579003072514, 4, 4, 1, NULL, 1.00, 0, '2026-07-03 06:07:14', '2026-07-03 06:07:14'),
  (1900000000000004725, 1900000000000000455, 2099383503295885313, 5, 5, 1, '第一次尝试，步骤写得清楚，我这种平时不进厨房的人也一次成功了。', 1.00, 0, '2026-07-28 16:48:47', '2026-07-28 16:48:47'),
  (1900000000000004726, 1900000000000000455, 2099705244425662466, 4, 4, 1, NULL, 1.00, 0, '2026-06-16 19:05:21', '2026-06-16 19:05:21'),
  (1900000000000004728, 1900000000000000455, 2099746244187779074, 1, 2, 0, NULL, 1.00, 0, '2026-08-28 13:12:26', '2026-08-28 13:12:26'),
  (1900000000000004729, 1900000000000000455, 2099751052210728961, 4, 5, 1, '还原度挺高，要是能标注下中途要不要翻面就更好了。', 1.00, 0, '2026-09-10 19:18:37', '2026-09-10 19:18:37'),
  (1900000000000004761, 1900000000000000462, 2099755347190607873, 5, 5, 1, NULL, 1.00, 0, '2026-08-13 18:46:32', '2026-08-13 18:46:32'),
  (1900000000000004763, 1900000000000000462, 2099696755372470274, 4, 4, 0, NULL, 1.00, 0, '2026-08-12 22:13:33', '2026-08-12 22:13:33'),
  (1900000000000004764, 1900000000000000462, 2105709796896272386, 5, 5, 1, '真的省事，洗的锅碗都比其他菜少。', 1.00, 0, '2026-08-27 04:18:11', '2026-08-27 04:18:11'),
  (1900000000000004765, 1900000000000000462, 2099696756802727938, 4, 3, 1, NULL, 1.00, 0, '2026-09-03 22:42:32', '2026-09-03 22:42:32'),
  (1900000000000004767, 1900000000000000462, 2105666523875917825, 4, 4, 0, '做法没问题，我换了个锅，时间要稍微加几分钟。', 1.00, 0, '2026-08-24 21:47:14', '2026-08-24 21:47:14'),
