  (1900000000000004915, 1900000000000000478, 2099698280006168577, 2, 2, 0, '做出来口感偏老，下次不会按这个时间来。', 1.00, 0, '2026-09-21 01:27:31', '2026-09-21 01:27:31'),
  (1900000000000004916, 1900000000000000478, 2099681025193185281, 5, 5, 1, '腌那十分钟真的有用，别偷懒跳过。', 1.00, 0, '2026-09-26 19:09:24', '2026-09-26 19:09:24'),
  (1900000000000004918, 1900000000000000478, 2099437330086760449, 2, 3, 0, '可能是我操作问题，最后成品和描述差挺远。', 1.00, 0, '2026-09-29 18:38:23', '2026-09-29 18:38:23'),
  (1900000000000004920, 1900000000000000478, 2099750963513782274, 5, 5, 1, NULL, 1.00, 0, '2026-09-18 14:02:24', '2026-09-18 14:02:24'),
  (1900000000000004922, 1900000000000000478, 2100119371360817154, 5, 5, 1, '第二次做，鸡翅处理得很嫩，一点都不柴，这点最惊喜。', 1.00, 0, '2026-09-17 19:54:49', '2026-09-17 19:54:49'),
  (1900000000000004936, 1900000000000000484, 2099723461747658753, 4, 3, 1, '上周做的，做出来了，卖相比菜谱图差一点，味道没差。', 1.00, 0, '2026-09-15 06:09:41', '2026-09-15 06:09:41'),
  (1900000000000004937, 1900000000000000484, 2100145795866087425, 3, 3, 0, NULL, 1.00, 0, '2026-08-17 19:23:17', '2026-08-17 19:23:17'),
  (1900000000000004939, 1900000000000000484, 2099424960438452226, 5, 5, 1, '照着方子，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-08-15 22:14:31', '2026-08-15 22:14:31'),
  (1900000000000004941, 1900000000000000484, 2100442915739328514, 5, 5, 1, '出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-09-26 11:14:04', '2026-09-26 11:14:04'),
  (1900000000000004943, 1900000000000000484, 2099746243478941698, 5, 5, 1, '第二次做，关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-10-01 13:56:02', '2026-10-01 13:56:02'),
