  (1900000000000006109, 2100408607871897602, 2099756063070220289, 1, 2, 0, '第二次做，咸得没法入口，建议把用量再核一下。', 1.00, 0, '2026-04-09 20:23:32', '2026-04-09 20:23:32'),
  (1900000000000006111, 2100408607871897602, 2099723556845113345, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 19:49:14', '2026-10-01 19:49:14'),
