  (1900000000000006117, 2100408607871897602, 2105687200876183554, 5, 5, 1, '关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-06-28 22:33:35', '2026-06-28 22:33:35'),
  (1900000000000006119, 2100408607871897602, 2099426390394126337, 5, 4, 1, NULL, 1.00, 0, '2026-07-01 10:36:04', '2026-07-01 10:36:04'),
  (1900000000000006120, 2100408607871897602, 2100442913398906882, 4, 3, 0, '照着方子，还原度挺高，要是能标注下中途要不要翻面就更好了。', 1.00, 0, '2026-07-20 08:48:07', '2026-07-20 08:48:07'),
  (1900000000000006121, 2100408607871897602, 2105709796896272386, 5, 5, 1, NULL, 1.00, 0, '2026-07-17 12:59:44', '2026-07-17 12:59:44'),
