  (1900000000000006125, 2100408607871897602, 2100415018777501697, 5, 5, 1, NULL, 1.00, 0, '2026-06-12 21:33:20', '2026-06-12 21:33:20'),
  (1900000000000006126, 2100408607871897602, 2100442917110865922, 5, 5, 1, NULL, 1.00, 0, '2026-09-07 14:32:20', '2026-09-07 14:32:20'),
  (1900000000000006128, 2100408607871897602, 2099380565668298753, 2, 2, 0, '第二次做，食材用量不太合理，我按量做出来太多了。', 1.00, 0, '2026-04-18 23:54:02', '2026-04-18 23:54:02'),
  (1900000000000006129, 2100408607871897602, 2099753167800889345, 4, 4, 1, '整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-09-06 21:12:13', '2026-09-06 21:12:13'),
  (1900000000000006131, 2100408607871897602, 2100139042453639170, 4, 4, 1, '上周做的，做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-05-15 13:50:48', '2026-05-15 13:50:48'),
  (1900000000000006132, 2100408607871897602, 2099701394633404418, 5, 5, 1, NULL, 1.00, 0, '2026-10-01 18:39:44', '2026-10-01 18:39:44'),
  (1900000000000006134, 2100408607871897602, 2099743112946905090, 5, 5, 1, '上周做的，味道很正，家常的香气一进门就闻到了。', 1.00, 0, '2026-07-07 15:00:39', '2026-07-07 15:00:39'),
  (1900000000000006136, 2100408607871897602, 2100427162000613377, 5, 4, 1, NULL, 1.00, 0, '2026-04-15 21:04:11', '2026-04-15 21:04:11'),
  (1900000000000006138, 2100408607871897602, 2100442919979769857, 2, 2, 0, '今天又做了一次，调料比例不太对，做完偏甜，家里人都没怎么动。', 1.00, 0, '2026-08-08 14:38:03', '2026-08-08 14:38:03'),
  (1900000000000006139, 2100408607871897602, 2099751052210728961, 5, 5, 1, NULL, 1.00, 0, '2026-06-23 21:32:11', '2026-06-23 21:32:11'),
  (1900000000000006140, 2100408607871897602, 2099428675450945537, 3, 3, 0, '做出来偏咸，下次要减量，这次只能凑合吃。', 1.00, 0, '2026-07-11 20:51:16', '2026-07-11 20:51:16'),
  (1900000000000006142, 2100408607871897602, 2099749705306468354, 5, 5, 1, NULL, 1.00, 0, '2026-04-09 21:42:03', '2026-04-09 21:42:03'),
  (1900000000000006144, 2100408607871897602, 2100118309295935490, 4, 4, 1, '做法没问题，我换了个锅，时间要稍微加几分钟。', 1.00, 0, '2026-07-19 22:19:11', '2026-07-19 22:19:11'),
  (1900000000000006145, 2100408607871897602, 2105707494147858434, 5, 5, 1, '家里人说比外卖强多了，还干净。', 1.00, 0, '2026-04-10 13:56:39', '2026-04-10 13:56:39'),
  (1900000000000006163, 2100443578560946177, 2105677244823224321, 5, 5, 1, NULL, 1.00, 0, '2026-08-26 11:10:07', '2026-08-26 11:10:07'),
