INSERT INTO t_dish_rating (id, dish_id, user_id, score, taste_score, cooked_flag, comment, weight, deleted, create_time, update_time) VALUES
  (1900000000000006238, 2100443628808708098, 2105667472463904769, 4, 4, 1, '做了两次才摸到火候，第一次略老。', 1.00, 0, '2026-06-23 18:15:14', '2026-06-23 18:15:14'),
  (1900000000000006239, 2100443628808708098, 2105681488087334913, 5, 5, 1, '第二次做，分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-09-04 08:49:16', '2026-09-04 08:49:16'),
  (1900000000000006241, 2100443628808708098, 2099705010635157506, 5, 5, 1, NULL, 1.00, 0, '2026-09-24 05:55:33', '2026-09-24 05:55:33'),
  (1900000000000006242, 2100443628808708098, 2100442912622960641, 3, 3, 0, '做法没问题，就是味道偏淡，得自己加重口。', 1.00, 0, '2026-06-26 20:14:50', '2026-06-26 20:14:50'),
