  (1900000000000006489, 2099752643919630338, 2100442919455481857, 4, 4, 1, NULL, 1.00, 0, '2026-08-24 06:42:57', '2026-08-24 06:42:57'),
  (1900000000000006491, 2099752643919630338, 2099696756802727938, 4, 3, 1, '味道可以，下次我想试试加香菜提味。', 1.00, 0, '2026-08-29 10:16:47', '2026-08-29 10:16:47'),
  (1900000000000006493, 2099752643919630338, 2099749704534716417, 4, 3, 1, NULL, 1.00, 0, '2026-04-25 19:34:46', '2026-04-25 19:34:46'),
  (1900000000000006495, 2099752643919630338, 2100134844089552898, 2, 2, 0, NULL, 1.00, 0, '2026-04-29 22:11:30', '2026-04-29 22:11:30'),
  (1900000000000006497, 2099752643919630338, 2099751052210728961, 3, 3, 0, '第一次尝试，味道普通，感觉外卖随便点一个都比这个强。', 1.00, 0, '2026-05-18 06:29:01', '2026-05-18 06:29:01'),
  (1900000000000006498, 2099752643919630338, 2105681488087334913, 5, 5, 1, NULL, 1.00, 0, '2026-08-15 09:54:32', '2026-08-15 09:54:32'),
  (1900000000000006499, 2099752643919630338, 2099697355321520129, 5, 4, 1, '上周做的，腌那十分钟真的有用，别偷懒跳过。', 1.00, 0, '2026-08-17 19:27:07', '2026-08-17 19:27:07'),
  (1900000000000006501, 2099752643919630338, 2099755579194339330, 5, 5, 1, '第一次尝试，味道层次挺清楚，不是一味的重口。', 1.00, 0, '2026-05-09 19:24:33', '2026-05-09 19:24:33'),
  (1900000000000006502, 2099752643919630338, 2099681025193185281, 5, 5, 1, '做完给室友分了一份，第二天问我要链接。', 1.00, 0, '2026-06-21 19:33:29', '2026-06-21 19:33:29'),
  (1900000000000006504, 2099752643919630338, 2099750963513782274, 5, 5, 1, NULL, 1.00, 0, '2026-09-12 22:09:40', '2026-09-12 22:09:40'),
  (1900000000000006506, 2099752643919630338, 2099426804636172290, 5, 5, 1, NULL, 1.00, 0, '2026-06-09 20:03:17', '2026-06-09 20:03:17'),
  (1900000000000006508, 2099752643919630338, 2099702594833494018, 4, 4, 1, NULL, 1.00, 0, '2026-06-12 22:10:31', '2026-06-12 22:10:31'),
  (1900000000000006510, 2099752643919630338, 2099746243478941698, 4, 3, 1, NULL, 1.00, 0, '2026-08-15 10:26:28', '2026-08-15 10:26:28'),
  (1900000000000006511, 2099752643919630338, 2105670358598041602, 5, 5, 1, '分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-08-28 11:30:11', '2026-08-28 11:30:11'),
  (1900000000000006513, 2099752643919630338, 2099701394633404418, 5, 4, 1, NULL, 1.00, 0, '2026-07-29 11:03:49', '2026-07-29 11:03:49'),
  (1900000000000006515, 2099752643919630338, 2105686609269604353, 4, 5, 1, NULL, 1.00, 0, '2026-09-14 21:58:22', '2026-09-14 21:58:22'),
  (1900000000000006517, 2099752643919630338, 2099427479453548545, 4, 4, 1, NULL, 1.00, 0, '2026-05-17 09:11:14', '2026-05-17 09:11:14'),
  (1900000000000006519, 2099752643919630338, 2105685384474116098, 5, 5, 1, '第一次尝试，这道土豆胡萝卜香炒我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-07-25 22:07:05', '2026-07-25 22:07:05'),
  (1900000000000006528, 2100415871160729602, 2099383579003072514, 1, 1, 0, '第二次做，味道很奇怪，家里人都不吃，最后倒掉了。', 1.00, 0, '2026-04-23 02:28:29', '2026-04-23 02:28:29'),
  (1900000000000006530, 2100415871160729602, 2105686689317896193, 4, 4, 0, NULL, 1.00, 0, '2026-09-14 14:25:00', '2026-09-14 14:25:00'),
  (1900000000000006531, 2100415871160729602, 2099424713016459266, 2, 1, 0, NULL, 1.00, 0, '2026-06-21 02:08:16', '2026-06-21 02:08:16'),
  (1900000000000006532, 2100415871160729602, 2099681709128970242, 5, 5, 0, '照着方子，以前在外面吃过，自己照着做居然还原了八九成。', 1.00, 0, '2026-06-12 09:45:46', '2026-06-12 09:45:46'),
  (1900000000000006533, 2100415871160729602, 2099701705271947265, 5, 5, 1, '今天又做了一次，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-08-02 12:16:29', '2026-08-02 12:16:29'),
  (1900000000000006534, 2100415871160729602, 2099743185026019329, 2, 2, 1, NULL, 1.00, 0, '2026-06-14 19:38:01', '2026-06-14 19:38:01'),
  (1900000000000006536, 2100415871160729602, 2105681825976270849, 4, 4, 0, NULL, 1.00, 0, '2026-04-15 21:57:52', '2026-04-15 21:57:52'),
  (1900000000000006538, 2100415871160729602, 2099428858867859457, 5, 5, 1, '今天又做了一次，炒的时间点给得准，照着数秒都不会老。', 1.00, 0, '2026-05-20 21:05:28', '2026-05-20 21:05:28'),
  (1900000000000006539, 2100415871160729602, 2099697354612682754, 5, 5, 1, NULL, 1.00, 0, '2026-09-28 12:03:48', '2026-09-28 12:03:48'),
  (1900000000000006540, 2100415871160729602, 2100442917958115330, 5, 5, 1, '今天又做了一次，第二次做了，把家常的味道调得更足一点，更合家人口味。', 1.00, 0, '2026-04-16 19:38:45', '2026-04-16 19:38:45'),
  (1900000000000006541, 2100415871160729602, 2099750964285534210, 4, 5, 1, NULL, 1.00, 0, '2026-04-09 12:40:27', '2026-04-09 12:40:27'),
  (1900000000000006543, 2100415871160729602, 2100442913856086018, 4, 5, 0, NULL, 1.00, 0, '2026-04-23 23:50:53', '2026-04-23 23:50:53'),
  (1900000000000006552, 2100443456284401665, 2100413821400178689, 5, 5, 1, NULL, 1.00, 0, '2026-06-21 20:38:21', '2026-06-21 20:38:21'),
  (1900000000000006553, 2100443456284401665, 2105666569564471297, 5, 5, 1, '炒的时间点给得准，照着数秒都不会老。', 1.00, 0, '2026-08-18 21:38:34', '2026-08-18 21:38:34'),
  (1900000000000006554, 2100443456284401665, 2105707494147858434, 5, 5, 1, '出锅前那勺芝麻油是灵魂，香气立刻上来了。', 1.00, 0, '2026-05-19 08:32:03', '2026-05-19 08:32:03'),
  (1900000000000006556, 2100443456284401665, 2099752498108952577, 5, 5, 1, '一人份的量刚好，不会做多做少。', 1.00, 0, '2026-06-26 08:51:24', '2026-06-26 08:51:24'),
  (1900000000000006558, 2100443456284401665, 2099752656385208322, 4, 3, 1, NULL, 1.00, 0, '2026-07-23 16:43:14', '2026-07-23 16:43:14'),
  (1900000000000006560, 2100443456284401665, 2105691607936253953, 5, 5, 1, NULL, 1.00, 0, '2026-05-21 17:57:54', '2026-05-21 17:57:54'),
  (1900000000000006561, 2100443456284401665, 2099753167800889345, 4, 5, 1, NULL, 1.00, 0, '2026-05-15 16:57:06', '2026-05-15 16:57:06'),
  (1900000000000006563, 2100443456284401665, 2105667669579415553, 5, 5, 1, NULL, 1.00, 0, '2026-05-29 21:27:17', '2026-05-29 21:27:17'),
