  (1900000000000006569, 2100443456284401665, 2099428168997126145, 5, 5, 1, NULL, 1.00, 0, '2026-07-30 20:45:35', '2026-07-30 20:45:35'),
  (1900000000000006570, 2100443456284401665, 2099426804636172290, 4, 5, 1, NULL, 1.00, 0, '2026-05-29 21:46:17', '2026-05-29 21:46:17'),
  (1900000000000006572, 2100443456284401665, 2099702580669329409, 5, 5, 1, '今天又做了一次，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-07-22 13:24:34', '2026-07-22 13:24:34'),
  (1900000000000006574, 2100443456284401665, 2099724074103459842, 5, 5, 1, NULL, 1.00, 0, '2026-05-22 14:46:10', '2026-05-22 14:46:10'),
