  (1900000000000006581, 2100443456284401665, 2099697410912825345, 1, 1, 0, NULL, 1.00, 0, '2026-09-29 00:51:09', '2026-09-29 00:51:09'),
  (1900000000000006583, 2100443456284401665, 2100442913398906882, 5, 5, 0, '第二次做，麻辣粉丝肉丝的用量给得刚好，不用自己再摸索，第一次做就很稳。', 1.00, 0, '2026-09-18 10:40:15', '2026-09-18 10:40:15'),
  (1900000000000006585, 2100443456284401665, 2099765319706210306, 1, 1, 0, '按方子做完全不成形，可能我火候差太远。', 1.00, 0, '2026-06-23 21:15:39', '2026-06-23 21:15:39'),
  (1900000000000006586, 2100443456284401665, 2099424713016459266, 5, 5, 1, '第一次尝试，按方子来的，一点没改，味道已经很好，没有踩雷。', 1.00, 0, '2026-04-17 02:20:50', '2026-04-17 02:20:50'),
  (1900000000000006587, 2100443456284401665, 2099756278732943361, 1, 2, 0, NULL, 1.00, 0, '2026-04-19 11:16:26', '2026-04-19 11:16:26'),
  (1900000000000006588, 2100443456284401665, 2099756620061208577, 4, 4, 1, '上周做的，香是挺香，就是收拾起来麻烦点。', 1.00, 0, '2026-08-10 12:50:05', '2026-08-10 12:50:05'),
  (1900000000000006589, 2100443456284401665, 2105672501321154561, 3, 4, 0, '今天又做了一次，中规中矩，照着做没失败，但也不会再做第二次。', 1.00, 0, '2026-08-24 11:50:16', '2026-08-24 11:50:16'),
  (1900000000000006591, 2100443456284401665, 2105681488087334913, 5, 4, 1, NULL, 1.00, 0, '2026-06-11 13:43:15', '2026-06-11 13:43:15'),
  (1900000000000006593, 2100443456284401665, 2105670358598041602, 5, 5, 0, NULL, 1.00, 0, '2026-04-09 16:09:18', '2026-04-09 16:09:18'),
  (1900000000000006606, 2099752747070148609, 2099724074103459842, 5, 5, 1, NULL, 1.00, 0, '2026-04-28 14:28:07', '2026-04-28 14:28:07'),
  (1900000000000006608, 2099752747070148609, 2105667472463904769, 5, 4, 1, NULL, 1.00, 0, '2026-07-03 18:24:20', '2026-07-03 18:24:20'),
  (1900000000000006610, 2099752747070148609, 2105687058194350082, 4, 4, 1, NULL, 1.00, 0, '2026-05-05 19:00:54', '2026-05-05 19:00:54'),
  (1900000000000006611, 2099752747070148609, 2099699301033979906, 5, 4, 1, NULL, 1.00, 0, '2026-09-06 12:49:16', '2026-09-06 12:49:16'),
  (1900000000000006612, 2099752747070148609, 2099743112946905090, 3, 3, 0, NULL, 1.00, 0, '2026-06-05 12:29:30', '2026-06-05 12:29:30'),
  (1900000000000006614, 2099752747070148609, 2100139475368726530, 5, 4, 1, NULL, 1.00, 0, '2026-08-21 05:12:35', '2026-08-21 05:12:35'),
  (1900000000000006616, 2099752747070148609, 2100119371360817154, 5, 5, 1, '食材都是冰箱里常备的，不用专门跑超市。', 1.00, 0, '2026-05-08 20:58:08', '2026-05-08 20:58:08'),
  (1900000000000006617, 2099752747070148609, 2099724431911145474, 3, 4, 1, '照着方子，没有想象中好，主要是土豆胡萝卜香煎的味道没出来。', 1.00, 0, '2026-04-10 01:01:49', '2026-04-10 01:01:49'),
  (1900000000000006618, 2099752747070148609, 2099753671771680770, 5, 4, 1, '上周做的，连着做了两次，第二次明显比第一次顺手。', 1.00, 0, '2026-05-28 07:47:56', '2026-05-28 07:47:56'),
  (1900000000000006620, 2099752747070148609, 2105707611408015361, 3, 3, 0, NULL, 1.00, 0, '2026-07-21 12:56:10', '2026-07-21 12:56:10'),
  (1900000000000006621, 2099752747070148609, 2100118309295935490, 4, 5, 1, NULL, 1.00, 0, '2026-08-24 08:09:35', '2026-08-24 08:09:35'),
  (1900000000000006622, 2099752747070148609, 2099698280673062914, 2, 2, 0, '今天又做了一次，调料比例不太对，做完偏甜，家里人都没怎么动。', 1.00, 0, '2026-08-11 12:41:11', '2026-08-11 12:41:11'),
  (1900000000000006623, 2099752747070148609, 2100135297292488705, 5, 5, 1, NULL, 1.00, 0, '2026-08-02 20:11:13', '2026-08-02 20:11:13'),
  (1900000000000006624, 2099752747070148609, 2105707284344578050, 5, 5, 1, '炒的时间点给得准，照着数秒都不会老。', 1.00, 0, '2026-07-24 21:58:42', '2026-07-24 21:58:42'),
  (1900000000000006626, 2099752747070148609, 2099681709128970242, 4, 4, 1, '照着方子，整体满意，如果能给个代替食材的建议会更好。', 1.00, 0, '2026-06-04 13:56:54', '2026-06-04 13:56:54'),
  (1900000000000006628, 2099752747070148609, 2105707494147858434, 5, 5, 1, NULL, 1.00, 0, '2026-04-16 20:09:02', '2026-04-16 20:09:02'),
  (1900000000000006630, 2099752747070148609, 2099433163855310849, 4, 4, 1, '照着方子，挺满意的，唯一遗憾是土豆胡萝卜香煎我没有买到新鲜的。', 1.00, 0, '2026-09-06 23:02:46', '2026-09-06 23:02:46'),
  (1900000000000006631, 2099752747070148609, 2099723811162542082, 5, 4, 1, '上周做的，这个做法把土豆胡萝卜香煎的鲜味全留住了。', 1.00, 0, '2026-04-07 13:32:04', '2026-04-07 13:32:04'),
  (1900000000000006633, 2099752747070148609, 2099383437885714434, 5, 5, 1, NULL, 1.00, 0, '2026-05-20 13:08:14', '2026-05-20 13:08:14'),
  (1900000000000006635, 2099752747070148609, 2105670358598041602, 4, 4, 1, '第二次做，味道可以，就是火候不太好掌握，我第一次稍微过了。', 1.00, 0, '2026-07-30 19:48:05', '2026-07-30 19:48:05'),
  (1900000000000006637, 2099752747070148609, 2099428007537393665, 4, 4, 1, '上周做的，做出来挺香，唯一的问题是油可以再少放一点。', 1.00, 0, '2026-08-09 17:12:21', '2026-08-09 17:12:21'),
  (1900000000000006639, 2099752747070148609, 2099701705271947265, 5, 5, 1, '分量标得准，两口人吃正好不剩。', 1.00, 0, '2026-04-27 16:50:20', '2026-04-27 16:50:20'),
  (1900000000000006641, 2099752747070148609, 2105672501321154561, 5, 5, 0, '照着方子，这道土豆胡萝卜香煎我一周做了三次，家里那位现在点名要吃。', 1.00, 0, '2026-09-04 20:55:51', '2026-09-04 20:55:51'),
  (1900000000000006643, 2099752747070148609, 2099433596644569090, 4, 4, 1, NULL, 1.00, 0, '2026-08-31 21:53:20', '2026-08-31 21:53:20'),
  (1900000000000006645, 2099752747070148609, 2099723461747658753, 5, 5, 1, NULL, 1.00, 0, '2026-06-19 07:00:27', '2026-06-19 07:00:27'),
  (1900000000000006647, 2099752747070148609, 2099701635050909697, 5, 5, 1, '第一次尝试，家里人说比外卖强多了，还干净。', 1.00, 0, '2026-06-23 17:49:31', '2026-06-23 17:49:31'),
  (1900000000000006672, 2100408557724798977, 2105682187139399682, 4, 4, 1, '好做，就是香辣胡椒干辣椒调味肉切的时候要费点工夫。', 1.00, 0, '2026-04-17 21:20:50', '2026-04-17 21:20:50'),
  (1900000000000006674, 2100408557724798977, 2099751661219475458, 4, 4, 1, NULL, 1.00, 0, '2026-09-08 18:48:41', '2026-09-08 18:48:41'),
  (1900000000000006676, 2100408557724798977, 2105682212728848385, 5, 5, 1, NULL, 1.00, 0, '2026-07-31 12:12:21', '2026-07-31 12:12:21'),
  (1900000000000006678, 2100408557724798977, 2105686689317896193, 5, 5, 1, NULL, 1.00, 0, '2026-08-12 19:41:12', '2026-08-12 19:41:12'),
  (1900000000000006679, 2100408557724798977, 2099755347190607873, 4, 5, 1, '今天又做了一次，可以，下次我会先把香辣胡椒干辣椒调味肉焯水再炒，口感应该更好。', 1.00, 0, '2026-09-15 20:07:55', '2026-09-15 20:07:55'),
  (1900000000000006681, 2100408557724798977, 2099765319706210306, 4, 4, 0, NULL, 1.00, 0, '2026-04-19 21:53:18', '2026-04-19 21:53:18'),
  (1900000000000006682, 2100408557724798977, 2100422849102667778, 4, 4, 0, '照着方子，挺好，就是调料里有一样我家没有，用别的代替了。', 1.00, 0, '2026-04-07 18:35:02', '2026-04-07 18:35:02'),
  (1900000000000006683, 2100408557724798977, 2100442917110865922, 5, 4, 1, NULL, 1.00, 0, '2026-05-10 07:23:45', '2026-05-10 07:23:45'),
  (1900000000000006685, 2100408557724798977, 2099390475495927810, 4, 5, 1, '挺好吃的，下次打算把糖减半，家里人不爱甜。', 1.00, 0, '2026-07-21 07:40:18', '2026-07-21 07:40:18'),
  (1900000000000006687, 2100408557724798977, 2099743112946905090, 5, 5, 1, NULL, 1.00, 0, '2026-09-17 19:19:40', '2026-09-17 19:19:40');
