  (1900000000000007131, 2100443237010382849, 2099697355321520129, 5, 5, 1, '关键一步说得很细，照着做没糊锅。', 1.00, 0, '2026-09-19 20:01:10', '2026-09-19 20:01:10'),
  (1900000000000007133, 2100443237010382849, 2099426804636172290, 5, 5, 1, '照着方子，做完给室友分了一份，第二天问我要链接。', 1.00, 0, '2026-04-28 20:39:29', '2026-04-28 20:39:29'),
  (1900000000000007135, 2100443237010382849, 2105681892892196865, 5, 5, 1, '照着方子，做完拍照发朋友圈，好几个人问我要菜谱。', 1.00, 0, '2026-09-02 19:46:38', '2026-09-02 19:46:38'),
