  (1900000000000007444, 2099701542419701762, 2105672958714200066, 5, 4, 1, '第二次做，味道层次挺清楚，不是一味的重口。', 1.00, 0, '2026-09-18 13:41:06', '2026-09-18 13:41:06'),
  (1900000000000007445, 2099701542419701762, 2099427252554285058, 4, 4, 1, '香是挺香，就是收拾起来麻烦点。', 1.00, 0, '2026-07-01 21:20:58', '2026-07-01 21:20:58'),
