INSERT INTO t_dish_comment (id, dish_id, user_id, content, rating, like_count, status, deleted, create_time, update_time) VALUES
  (1900000000000000491, 1900000000000000001, 2105666748212461570, '照着方子，味道普通，感觉外卖随便点一个都比这个强。', 3, 0, 1, 0, '2026-08-27 17:51:40', '2026-08-27 17:51:40'),
  (1900000000000000494, 1900000000000000001, 2105682040150016001, '照着方子，腌那十分钟真的有用，别偷懒跳过。', 5, 21, 1, 0, '2026-08-27 20:00:48', '2026-08-27 20:00:48'),
  (1900000000000000496, 1900000000000000001, 2099335487637712897, '第二次做，成功了，感谢。下次试试加别的配菜。', 4, 0, 1, 0, '2026-08-24 04:21:13', '2026-08-24 04:21:13'),
  (1900000000000000498, 1900000000000000001, 2099723461747658753, '配米饭配面条都行，怎么搭都不出错。', 5, 3, 1, 0, '2026-09-01 19:28:06', '2026-09-01 19:28:06'),
  (1900000000000000501, 1900000000000000001, 2100442916662075394, '第二次做，这个做法把西兰花的鲜味全留住了。', 5, 8, 1, 0, '2026-08-27 14:10:53', '2026-08-27 14:10:53'),
  (1900000000000000504, 1900000000000000001, 2105666569564471297, '第二次做，按这个量放调料，咸淡刚刚好，不用再补救。', 5, 37, 1, 0, '2026-09-27 08:48:52', '2026-09-27 08:48:52'),
  (1900000000000000507, 1900000000000000001, 2105667472463904769, '火候说得很明白，跟着时间走不会老。', 5, 11, 1, 0, '2026-08-04 13:11:09', '2026-08-04 13:11:09'),
