  (1900000000000001232, 1900000000000000078, 2099750964285534210, '按这个量放调料，咸淡刚刚好，不用再补救。', 5, 16, 1, 0, '2026-09-21 20:47:43', '2026-09-21 20:47:43'),
  (1900000000000001234, 1900000000000000078, 2099724074103459842, '第二次做，食材搭配有点奇怪，我个人不太习惯。', 3, 0, 1, 0, '2026-08-12 02:32:07', '2026-08-12 02:32:07'),
  (1900000000000001236, 1900000000000000078, 2099755611784081409, '第一次尝试，做法没问题，我换了个锅，时间要稍微加几分钟。', 4, 20, 1, 0, '2026-09-02 18:24:09', '2026-09-02 18:24:09'),
  (1900000000000001241, 1900000000000000078, 2099707576462901250, '家人评价不错，我自己觉得可以再辣一点。', 4, 2, 1, 0, '2026-08-29 18:21:56', '2026-08-29 18:21:56'),
  (1900000000000001243, 1900000000000000078, 2099749704534716417, '第一次尝试，整体不错，唯一是步骤里水量说得有点模糊。', 4, 1, 1, 0, '2026-09-23 19:32:22', '2026-09-23 19:32:22'),
  (1900000000000001246, 1900000000000000078, 2105677399211360257, '味道比较寡淡，需要自己大改，不太推荐照搬。', 2, 0, 1, 0, '2026-08-27 08:32:12', '2026-08-27 08:32:12'),
  (1900000000000001249, 1900000000000000078, 2100442914833358849, '连着做了两次，第二次明显比第一次顺手。', 5, 41, 1, 0, '2026-09-11 11:17:30', '2026-09-11 11:17:30'),
  (1900000000000001251, 1900000000000000078, 2105667472463904769, '上周做的，味道不错，就是青椒可以再多一点，吃着不过瘾。', 4, 7, 1, 0, '2026-08-13 14:26:29', '2026-08-13 14:26:29'),
  (1900000000000001253, 1900000000000000078, 2099426390394126337, '味道不错，就是青椒可以再多一点，吃着不过瘾。', 4, 7, 1, 0, '2026-09-15 14:53:36', '2026-09-15 14:53:36'),
  (1900000000000001255, 1900000000000000078, 2099697410912825345, '家里人说比外卖强多了，还干净。', 5, 2, 1, 0, '2026-09-08 12:40:25', '2026-09-08 12:40:25'),
  (1900000000000001257, 1900000000000000078, 2099429064401338370, '上周做的，这道青椒肉丝我一周做了三次，家里那位现在点名要吃。', 5, 0, 1, 0, '2026-09-24 07:17:20', '2026-09-24 07:17:20'),
  (1900000000000001259, 1900000000000000078, 2105667669579415553, '今天又做了一次，味道不错，就是青椒可以再多一点，吃着不过瘾。', 4, 0, 1, 0, '2026-08-17 19:48:40', '2026-08-17 19:48:40'),
