INSERT INTO t_dish_comment (id, dish_id, user_id, content, rating, like_count, status, deleted, create_time, update_time) VALUES
  (1900000000000001279, 1900000000000000084, 2099390475495927810, '第一次尝试，不错，就是最后装盘不太好看，不影响吃。', 4, 4, 1, 0, '2026-07-01 20:17:57', '2026-07-01 20:17:57'),
  (1900000000000001283, 1900000000000000084, 2100120517366304770, '还原度挺高，要是能标注下中途要不要翻面就更好了。', 4, 1, 1, 0, '2026-07-23 23:24:39', '2026-07-23 23:24:39'),
  (1900000000000001286, 1900000000000000084, 2099751660376420354, '第一次尝试，配米饭配面条都行，怎么搭都不出错。', 5, 1, 1, 0, '2026-05-21 08:09:58', '2026-05-21 08:09:58'),
  (1900000000000001288, 1900000000000000084, 2099751786029379585, '整体挺好，下次我会少放一点盐，偏咸了些。', 4, 0, 1, 0, '2026-07-12 19:04:36', '2026-07-12 19:04:36'),
  (1900000000000001291, 1900000000000000084, 2099344911148261377, '已经加入我的常做清单，隔几天就要做一次。', 5, 4, 1, 0, '2026-06-23 07:42:13', '2026-06-23 07:42:13'),
  (1900000000000001294, 1900000000000000084, 2099429020906405889, '腌那十分钟真的有用，别偷懒跳过。', 5, 11, 1, 0, '2026-08-05 06:07:52', '2026-08-05 06:07:52'),
  (1900000000000001296, 1900000000000000084, 2099428764521185282, '今天又做了一次，味道很正，鱼香的香气一进门就闻到了。', 5, 9, 1, 0, '2026-09-08 09:04:56', '2026-09-08 09:04:56'),
  (1900000000000001298, 1900000000000000084, 2100119371360817154, '味道很奇怪，家里人都不吃，最后倒掉了。', 1, 0, 1, 0, '2026-06-02 23:47:42', '2026-06-02 23:47:42'),
  (1900000000000001301, 1900000000000000084, 2099701394633404418, '第一次尝试，不功不过，做完没什么成就感。', 3, 2, 1, 0, '2026-07-09 17:30:56', '2026-07-09 17:30:56'),
  (1900000000000001305, 1900000000000000084, 2105681488087334913, '有点失望，味道和想象中差不少。', 2, 0, 1, 0, '2026-07-14 04:50:29', '2026-07-14 04:50:29'),
  (1900000000000001308, 1900000000000000084, 2100442915739328514, '上周做的，做了两次才摸到火候，第一次略老。', 4, 6, 1, 0, '2026-08-18 20:04:22', '2026-08-18 20:04:22'),
  (1900000000000001312, 1900000000000000084, 2100442917958115330, '火候说得很明白，跟着时间走不会老。', 5, 4, 1, 0, '2026-08-16 18:53:34', '2026-08-16 18:53:34'),
  (1900000000000001317, 1900000000000000084, 2105682040150016001, '上周做的，配米饭配面条都行，怎么搭都不出错。', 5, 5, 1, 0, '2026-05-28 07:12:55', '2026-05-28 07:12:55'),
  (1900000000000001319, 1900000000000000084, 2100442919979769857, '这道鱼香肉丝我一周做了三次，家里那位现在点名要吃。', 5, 17, 1, 0, '2026-08-08 12:27:44', '2026-08-08 12:27:44'),
  (1900000000000001321, 1900000000000000084, 2099426141265051649, '上周做的，这道鱼香肉丝我一周做了三次，家里那位现在点名要吃。', 5, 20, 1, 0, '2026-05-26 19:04:40', '2026-05-26 19:04:40'),
  (1900000000000001323, 1900000000000000084, 2099696756802727938, '第一次尝试，味道一般，没什么惊艳的，但也算能吃。', 3, 2, 1, 0, '2026-08-22 21:48:29', '2026-08-22 21:48:29'),
  (1900000000000001325, 1900000000000000084, 2105686689317896193, '第二次做，做出来了，卖相比菜谱图差一点，味道没差。', 4, 0, 1, 0, '2026-09-22 18:27:39', '2026-09-22 18:27:39'),
  (1900000000000001327, 1900000000000000084, 2099723461747658753, '第二次做，第二次做了，把鱼香的味道调得更足一点，更合家人口味。', 5, 9, 1, 0, '2026-06-10 12:52:04', '2026-06-10 12:52:04'),
  (1900000000000001330, 1900000000000000084, 2099752497320423425, '今天又做了一次，整体不错，唯一是步骤里水量说得有点模糊。', 4, 2, 1, 0, '2026-07-05 07:57:14', '2026-07-05 07:57:14'),
  (1900000000000001334, 1900000000000000084, 2100442918482403330, '以前在外面吃过，自己照着做居然还原了八九成。', 5, 2, 1, 0, '2026-08-13 17:23:42', '2026-08-13 17:23:42'),
  (1900000000000001336, 1900000000000000084, 2099746243478941698, '第二次做，第一次做稍微咸了点，第二次减量正好。', 4, 3, 1, 0, '2026-05-14 02:56:10', '2026-05-14 02:56:10'),
  (1900000000000001338, 1900000000000000084, 2105666930429804546, '今天又做了一次，做出来挺香，唯一的问题是油可以再少放一点。', 4, 8, 1, 0, '2026-09-28 22:30:17', '2026-09-28 22:30:17'),
  (1900000000000001340, 1900000000000000084, 2099429064401338370, '第二次做，按这个量放调料，咸淡刚刚好，不用再补救。', 5, 12, 1, 0, '2026-09-08 12:07:01', '2026-09-08 12:07:01'),
  (1900000000000001342, 1900000000000000084, 2099380565668298753, '第一次尝试，食材都是冰箱里常备的，不用专门跑超市。', 5, 13, 1, 0, '2026-09-08 18:52:30', '2026-09-08 18:52:30'),
  (1900000000000001344, 1900000000000000084, 2105677399211360257, '上周做的，食材都是冰箱里常备的，不用专门跑超市。', 5, 9, 1, 0, '2026-06-05 18:18:35', '2026-06-05 18:18:35'),
  (1900000000000001369, 1900000000000000092, 2100442913856086018, '照着方子，没有想象中好，主要是五花肉的味道没出来。', 3, 2, 1, 0, '2026-09-12 17:15:11', '2026-09-12 17:15:11'),
