  (1900000000000003384, 1900000000000000303, 2100415018777501697, '上周做的，腌那十分钟真的有用，别偷懒跳过。', 5, 3, 1, 0, '2026-09-27 09:13:01', '2026-09-27 09:13:01'),
  (1900000000000003388, 1900000000000000303, 2105675867279572993, '味道一般，没什么惊艳的，但也算能吃。', 3, 2, 1, 0, '2026-09-28 20:52:19', '2026-09-28 20:52:19'),
  (1900000000000003391, 1900000000000000303, 2099752498108952577, '做出来的卖相一般，但味道是真的好。', 4, 7, 1, 0, '2026-09-28 16:19:17', '2026-09-28 16:19:17');
INSERT INTO t_dish_comment (id, dish_id, user_id, content, rating, like_count, status, deleted, create_time, update_time) VALUES
  (1900000000000003396, 1900000000000000303, 2100413821400178689, '今天又做了一次，不错，就是最后装盘不太好看，不影响吃。', 4, 5, 1, 0, '2026-09-25 16:18:55', '2026-09-25 16:18:55'),
  (1900000000000003398, 1900000000000000303, 2105670358598041602, '第二次做，做出来偏咸，我按方子放的盐，可能不适合我家口味。', 2, 0, 1, 0, '2026-09-23 15:20:43', '2026-09-23 15:20:43'),
  (1900000000000003400, 1900000000000000303, 2100120517366304770, '第二次做，家里人都吃完了，说明没问题，下次多做点。', 4, 0, 1, 0, '2026-09-17 05:13:30', '2026-09-17 05:13:30'),
  (1900000000000003402, 1900000000000000303, 2099751661219475458, '调料比例不太对，做完偏甜，家里人都没怎么动。', 2, 0, 1, 0, '2026-09-18 21:25:48', '2026-09-18 21:25:48'),
  (1900000000000003404, 1900000000000000303, 2100118309295935490, '整体不错，唯一是步骤里水量说得有点模糊。', 4, 2, 1, 0, '2026-09-23 17:40:16', '2026-09-23 17:40:16'),
  (1900000000000003406, 1900000000000000303, 2100442912098672641, '第一次做稍微咸了点，第二次减量正好。', 4, 2, 1, 0, '2026-09-27 18:34:08', '2026-09-27 18:34:08'),
  (1900000000000003408, 1900000000000000303, 2105667474145820673, '上周做的，有点失望，味道和想象中差不少。', 2, 0, 1, 0, '2026-09-26 21:25:40', '2026-09-26 21:25:40'),
  (1900000000000003433, 1900000000000000310, 2100442912098672641, '出锅前那勺芝麻油是灵魂，香气立刻上来了。', 5, 33, 1, 0, '2026-08-22 19:33:14', '2026-08-22 19:33:14'),
  (1900000000000003436, 1900000000000000310, 2099379216679469057, '比我想象中简单，重点步骤都点出来了。', 5, 1, 1, 0, '2026-09-02 18:23:00', '2026-09-02 18:23:00'),
  (1900000000000003439, 1900000000000000310, 2099701635050909697, '第一次尝试，味道很正，清甜的香气一进门就闻到了。', 5, 0, 1, 0, '2026-08-15 20:54:34', '2026-08-15 20:54:34'),
  (1900000000000003442, 1900000000000000310, 2099724470062534657, '没有想象中好，主要是排骨的味道没出来。', 3, 3, 1, 0, '2026-09-07 14:02:49', '2026-09-07 14:02:49'),
  (1900000000000003444, 1900000000000000310, 2099751052210728961, '挺好吃的，就是感觉少了一点点酸味。', 4, 4, 1, 0, '2026-08-23 12:59:48', '2026-08-23 12:59:48'),
  (1900000000000003446, 1900000000000000310, 2099702580669329409, '上周做的，做完给室友分了一份，第二天问我要链接。', 5, 19, 1, 0, '2026-09-15 09:27:24', '2026-09-15 09:27:24'),
  (1900000000000003448, 1900000000000000310, 2099701634144940033, '挺满意的，唯一遗憾是排骨我没有买到新鲜的。', 4, 1, 1, 0, '2026-09-15 11:25:34', '2026-09-15 11:25:34'),
  (1900000000000003450, 1900000000000000310, 2099751786029379585, '食材都是冰箱里常备的，不用专门跑超市。', 5, 15, 1, 0, '2026-09-05 12:06:02', '2026-09-05 12:06:02'),
  (1900000000000003452, 1900000000000000310, 2100145795866087425, '成功了，感谢。下次试试加别的配菜。', 4, 11, 1, 0, '2026-09-11 18:41:15', '2026-09-11 18:41:15'),
  (1900000000000003455, 1900000000000000310, 2105687058194350082, '第二次做，好做，就是排骨切的时候要费点工夫。', 4, 6, 1, 0, '2026-09-09 18:56:00', '2026-09-09 18:56:00'),
  (1900000000000003458, 1900000000000000310, 2099723461747658753, '第一次尝试，还可以，主要是我刀工不行，切得不均匀。', 4, 2, 1, 0, '2026-08-12 12:38:33', '2026-08-12 12:38:33'),
  (1900000000000003460, 1900000000000000310, 2105667671450075137, '味道可以，就是火候不太好掌握，我第一次稍微过了。', 4, 1, 1, 0, '2026-09-20 22:58:08', '2026-09-20 22:58:08'),
  (1900000000000003462, 1900000000000000310, 2105691607936253953, '味道很正，清甜的香气一进门就闻到了。', 5, 7, 1, 0, '2026-09-28 17:09:10', '2026-09-28 17:09:10'),
  (1900000000000003464, 1900000000000000310, 2099390475495927810, '上周做的，可能是我操作问题，最后成品和描述差挺远。', 2, 0, 1, 0, '2026-08-07 07:21:48', '2026-08-07 07:21:48'),
  (1900000000000003470, 1900000000000000310, 2099755579194339330, '第二次做，排骨处理得很嫩，一点都不柴，这点最惊喜。', 5, 4, 1, 0, '2026-08-13 20:51:29', '2026-08-13 20:51:29'),
  (1900000000000003482, 1900000000000000317, 2100145795866087425, '上周做的，做出来了，卖相比菜谱图差一点，味道没差。', 4, 3, 1, 0, '2026-09-28 00:12:02', '2026-09-28 00:12:02'),
  (1900000000000003486, 1900000000000000317, 2105681822776016897, '味道稳，就是汤汁有点多，下次多收一会儿。', 4, 2, 1, 0, '2026-09-30 13:16:04', '2026-09-30 13:16:04'),
  (1900000000000003488, 1900000000000000317, 2100139475368726530, '第一次尝试，关键一步说得很细，照着做没糊锅。', 5, 23, 1, 0, '2026-09-24 11:42:18', '2026-09-24 11:42:18'),
  (1900000000000003490, 1900000000000000317, 2099428254183440385, '第一次尝试，这个搭配真的吃不惯，做完浪费食材了。', 1, 0, 1, 0, '2026-09-26 15:20:38', '2026-09-26 15:20:38'),
  (1900000000000003492, 1900000000000000317, 2099752563540094978, '不错，下次提前腌久一点应该更入味。', 4, 1, 1, 0, '2026-09-27 11:03:52', '2026-09-27 11:03:52'),
  (1900000000000003494, 1900000000000000317, 2099379216679469057, '排骨的处理没讲清楚，我做出来有点腥。', 2, 0, 1, 0, '2026-09-24 22:18:04', '2026-09-24 22:18:04'),
  (1900000000000003501, 1900000000000000317, 2099743185026019329, '今天又做了一次，步骤很清楚，新手也能做，只是备料比我预想的花时间。', 4, 4, 1, 0, '2026-09-25 09:32:10', '2026-09-25 09:32:10'),
  (1900000000000003503, 1900000000000000317, 2099724431911145474, '照着方子，排骨的处理没讲清楚，我做出来有点腥。', 2, 0, 1, 0, '2026-09-28 09:16:38', '2026-09-28 09:16:38'),
  (1900000000000003505, 1900000000000000317, 2099697355321520129, '味道真不错，就是耗时比写的时间长一些。', 4, 4, 1, 0, '2026-09-29 17:01:38', '2026-09-29 17:01:38'),
  (1900000000000003507, 1900000000000000317, 2105707611408015361, '食材都是冰箱里常备的，不用专门跑超市。', 5, 10, 1, 0, '2026-09-29 13:07:38', '2026-09-29 13:07:38'),
  (1900000000000003509, 1900000000000000317, 2099753672547627009, '今天又做了一次，家里老人牙口不好，做软一点正好合适。', 5, 17, 1, 0, '2026-09-25 10:01:38', '2026-09-25 10:01:38'),
  (1900000000000003511, 1900000000000000317, 2100442918482403330, '第二次做，味道普通，感觉外卖随便点一个都比这个强。', 3, 2, 1, 0, '2026-09-23 18:46:49', '2026-09-23 18:46:49'),
  (1900000000000003517, 1900000000000000317, 2099701394633404418, '成功了，就是最后收汁有点久，稍微干了一点。', 4, 5, 1, 0, '2026-09-30 00:21:19', '2026-09-30 00:21:19'),
  (1900000000000003519, 1900000000000000317, 2099751661219475458, '照着方子，做完拍照发朋友圈，好几个人问我要菜谱。', 5, 2, 1, 0, '2026-09-25 13:52:19', '2026-09-25 13:52:19'),
  (1900000000000003540, 1900000000000000323, 2100442917110865922, '第二次做，这道菜让我对下厨有信心了，谢谢方子。', 5, 16, 1, 0, '2026-09-26 15:02:03', '2026-09-26 15:02:03'),
  (1900000000000003545, 1900000000000000323, 2099723461747658753, '上周做的，步骤里的时间不太准，我按着做有点糊了。', 2, 0, 1, 0, '2026-09-29 09:12:30', '2026-09-29 09:12:30'),
  (1900000000000003548, 1900000000000000323, 2105681892892196865, '第一次尝试，第一次做就成功了，很有成就感。', 5, 0, 1, 0, '2026-09-28 13:52:50', '2026-09-28 13:52:50'),
  (1900000000000003550, 1900000000000000323, 2099383437885714434, '这道南瓜燕麦粥我一周做了三次，家里那位现在点名要吃。', 5, 0, 1, 0, '2026-09-27 21:35:04', '2026-09-27 21:35:04'),
  (1900000000000003552, 1900000000000000323, 2099433163855310849, '今天又做了一次，孩子平时挑食，这次居然添了半碗饭。', 5, 14, 1, 0, '2026-09-29 19:19:06', '2026-09-29 19:19:06'),
  (1900000000000003554, 1900000000000000323, 2099431876065607681, '第一次尝试，味道可以，就是火候不太好掌握，我第一次稍微过了。', 4, 0, 1, 0, '2026-09-30 14:40:13', '2026-09-30 14:40:13'),
  (1900000000000003557, 1900000000000000323, 2100122576090091521, '步骤很清楚，新手也能做，只是备料比我预想的花时间。', 4, 3, 1, 0, '2026-09-28 08:46:36', '2026-09-28 08:46:36'),
  (1900000000000003559, 1900000000000000323, 2105687058194350082, '今天又做了一次，关键一步说得很细，照着做没糊锅。', 5, 17, 1, 0, '2026-10-01 20:05:12', '2026-10-01 20:05:12'),
  (1900000000000003561, 1900000000000000323, 2099750964285534210, '整体挺好，下次我会少放一点盐，偏咸了些。', 4, 4, 1, 0, '2026-10-01 20:11:23', '2026-10-01 20:11:23'),
  (1900000000000003563, 1900000000000000323, 2105682083112271873, '上周做的，家里人说比外卖强多了，还干净。', 5, 0, 1, 0, '2026-10-01 20:13:44', '2026-10-01 20:13:44'),
  (1900000000000003577, 1900000000000000327, 2099699301033979906, '第二次做，家里老人牙口不好，做软一点正好合适。', 5, 1, 1, 0, '2026-09-30 07:57:09', '2026-09-30 07:57:09'),
  (1900000000000003579, 1900000000000000327, 2100406228522950657, '收汁那一步别省，做出来味道完全不一样，香得很。', 5, 3, 1, 0, '2026-09-25 16:56:52', '2026-09-25 16:56:52'),
  (1900000000000003587, 1900000000000000327, 2099723556845113345, '第一次尝试，食材搭配有点奇怪，我个人不太习惯。', 3, 0, 1, 0, '2026-09-26 23:24:47', '2026-09-26 23:24:47'),
  (1900000000000003591, 1900000000000000327, 2100442912622960641, '第二次做了，把清甜的味道调得更足一点，更合家人口味。', 5, 15, 1, 0, '2026-10-01 21:16:20', '2026-10-01 21:16:20'),
  (1900000000000003594, 1900000000000000327, 2099380565668298753, '调料清单短，厨房小白也不会手忙脚乱。', 5, 5, 1, 0, '2026-09-28 08:49:47', '2026-09-28 08:49:47'),
  (1900000000000003596, 1900000000000000327, 2100442917568045058, '今天又做了一次，步骤写得清楚，我这种平时不进厨房的人也一次成功了。', 5, 0, 1, 0, '2026-09-29 23:36:38', '2026-09-29 23:36:38'),
  (1900000000000003598, 1900000000000000327, 2100415018777501697, '一人份的量刚好，不会做多做少。', 5, 3, 1, 0, '2026-09-23 15:44:02', '2026-09-23 15:44:02'),
  (1900000000000003600, 1900000000000000327, 2099426804636172290, '今天又做了一次，冷藏后再热一遍，味道居然更进去了。', 5, 0, 1, 0, '2026-09-27 11:20:19', '2026-09-27 11:20:19'),
  (1900000000000003602, 1900000000000000327, 2099437330086760449, '火候说得很明白，跟着时间走不会老。', 5, 16, 1, 0, '2026-09-25 11:09:00', '2026-09-25 11:09:00'),
  (1900000000000003606, 1900000000000000327, 2099433596644569090, '上周做的，做完一大锅，第二天热一下味道也没散。', 5, 3, 1, 0, '2026-09-29 12:31:41', '2026-09-29 12:31:41'),
  (1900000000000003608, 1900000000000000327, 2100442914309070850, '这道菜让我对下厨有信心了，谢谢方子。', 5, 9, 1, 0, '2026-09-28 10:22:13', '2026-09-28 10:22:13'),
  (1900000000000003611, 1900000000000000327, 2105666571758092290, '照着方子，做完一大锅，第二天热一下味道也没散。', 5, 1, 1, 0, '2026-09-28 19:24:48', '2026-09-28 19:24:48'),
  (1900000000000003613, 1900000000000000327, 2105675867279572993, '第一次尝试，做出来了，家里人反应平平，可能不合我们口味。', 3, 3, 1, 0, '2026-09-29 08:01:37', '2026-09-29 08:01:37'),
  (1900000000000003616, 1900000000000000327, 2099681709128970242, '咸得没法入口，建议把用量再核一下。', 1, 0, 1, 0, '2026-09-25 14:14:41', '2026-09-25 14:14:41'),
  (1900000000000003618, 1900000000000000327, 2099698692641796098, '还原度挺高，要是能标注下中途要不要翻面就更好了。', 4, 2, 1, 0, '2026-09-27 20:13:10', '2026-09-27 20:13:10'),
  (1900000000000003620, 1900000000000000327, 2105709796896272386, '分量标得准，两口人吃正好不剩。', 5, 9, 1, 0, '2026-09-28 17:40:59', '2026-09-28 17:40:59'),
  (1900000000000003622, 1900000000000000327, 2099701705271947265, '可以，下次我会先把排骨焯水再炒，口感应该更好。', 4, 4, 1, 0, '2026-09-29 22:59:40', '2026-09-29 22:59:40'),
  (1900000000000003624, 1900000000000000327, 2100442916662075394, '上周做的，味道真不错，就是耗时比写的时间长一些。', 4, 4, 1, 0, '2026-09-29 08:37:04', '2026-09-29 08:37:04'),
  (1900000000000003626, 1900000000000000327, 2099702580669329409, '照着方子，味道比较寡淡，需要自己大改，不太推荐照搬。', 2, 0, 1, 0, '2026-09-27 18:03:36', '2026-09-27 18:03:36'),
  (1900000000000003630, 1900000000000000327, 2105677399211360257, '今天又做了一次，排骨的用量给得刚好，不用自己再摸索，第一次做就很稳。', 5, 0, 1, 0, '2026-09-26 20:04:11', '2026-09-26 20:04:11'),
  (1900000000000003632, 1900000000000000327, 2099750963513782274, '上周做的，汤汁拌饭一绝，我一个人能干掉两碗。', 5, 28, 1, 0, '2026-09-27 21:14:42', '2026-09-27 21:14:42'),
  (1900000000000003634, 1900000000000000327, 2105682212728848385, '照着方子，味道可以，就是火候不太好掌握，我第一次稍微过了。', 4, 1, 1, 0, '2026-09-29 18:55:51', '2026-09-29 18:55:51'),
  (1900000000000003636, 1900000000000000327, 2099429064401338370, '照着方子，排骨的用量给得刚好，不用自己再摸索，第一次做就很稳。', 5, 2, 1, 0, '2026-09-25 23:29:57', '2026-09-25 23:29:57'),
  (1900000000000003638, 1900000000000000327, 2105687200876183554, '排骨处理得很嫩，一点都不柴，这点最惊喜。', 5, 2, 1, 0, '2026-09-28 13:25:41', '2026-09-28 13:25:41'),
  (1900000000000003640, 1900000000000000327, 2099383579003072514, '今天又做了一次，食材都是冰箱里常备的，不用专门跑超市。', 5, 0, 1, 0, '2026-09-25 21:39:07', '2026-09-25 21:39:07'),
  (1900000000000003643, 1900000000000000327, 2100121454612893698, '做出来挺满意，唯一是我把时间看错，多炖了十分钟。', 4, 1, 1, 0, '2026-09-30 18:53:22', '2026-09-30 18:53:22'),
  (1900000000000003647, 1900000000000000327, 2099755611784081409, '排骨的处理没讲清楚，我做出来有点腥。', 2, 0, 1, 0, '2026-09-26 11:21:26', '2026-09-26 11:21:26'),
  (1900000000000003649, 1900000000000000327, 2099428168997126145, '这个做法把排骨的鲜味全留住了。', 5, 7, 1, 0, '2026-09-27 16:11:25', '2026-09-27 16:11:25'),
  (1900000000000003677, 1900000000000000334, 2105709470025773057, '第二次做，失败了，不知道哪一步出了问题，最后没敢吃。', 1, 0, 1, 0, '2026-08-07 19:41:11', '2026-08-07 19:41:11'),
  (1900000000000003679, 1900000000000000334, 2099705547174719489, '第二次做，做出来的卖相一般，但味道是真的好。', 4, 3, 1, 0, '2026-06-20 20:30:42', '2026-06-20 20:30:42'),
  (1900000000000003681, 1900000000000000334, 2099743278462529538, '平时不爱吃这个的人都能接受，说明真的不难吃。', 5, 35, 1, 0, '2026-08-03 18:23:46', '2026-08-03 18:23:46'),
  (1900000000000003684, 1900000000000000334, 2100442915294732290, '味道可以，下次我想试试加香菜提味。', 4, 0, 1, 0, '2026-07-25 18:05:38', '2026-07-25 18:05:38'),
  (1900000000000003687, 1900000000000000334, 2099681709128970242, '第一次尝试，家人评价不错，我自己觉得可以再辣一点。', 4, 0, 1, 0, '2026-06-23 18:19:04', '2026-06-23 18:19:04'),
