  (1900000000000004038, 1900000000000000376, 2099707576462901250, '今天又做了一次，可以，下次我会先把面条焯水再炒，口感应该更好。', 4, 0, 1, 0, '2026-09-18 19:15:59', '2026-09-18 19:15:59'),
  (1900000000000004041, 1900000000000000376, 2105681825976270849, '照着方子，挺满意的，唯一遗憾是面条我没有买到新鲜的。', 4, 1, 1, 0, '2026-09-18 20:09:00', '2026-09-18 20:09:00'),
  (1900000000000004043, 1900000000000000376, 2105707494147858434, '第二次做，真的省事，洗的锅碗都比其他菜少。', 5, 40, 1, 0, '2026-09-10 18:40:51', '2026-09-10 18:40:51'),
  (1900000000000004046, 1900000000000000376, 2099707575057809409, '今天又做了一次，好做，就是面条切的时候要费点工夫。', 4, 6, 1, 0, '2026-09-18 17:24:27', '2026-09-18 17:24:27'),
  (1900000000000004049, 1900000000000000376, 2099750963513782274, '照着方子，第一次做就成功了，很有成就感。', 5, 0, 1, 0, '2026-09-23 21:17:35', '2026-09-23 21:17:35'),
  (1900000000000004054, 1900000000000000376, 2105681488087334913, '有点失望，味道和想象中差不少。', 2, 0, 1, 0, '2026-09-22 19:26:18', '2026-09-22 19:26:18'),
  (1900000000000004065, 1900000000000000383, 2099752498108952577, '第一次尝试，蛮好吃的，就是分量偏少，两个人吃略紧。', 4, 0, 1, 0, '2026-07-16 23:34:29', '2026-07-16 23:34:29'),
  (1900000000000004069, 1900000000000000383, 2100122576090091521, '关键一步说得很细，照着做没糊锅。', 5, 3, 1, 0, '2026-06-12 10:30:07', '2026-06-12 10:30:07'),
  (1900000000000004071, 1900000000000000383, 2099753791607140354, '第一次尝试，这道炸酱面我一周做了三次，家里那位现在点名要吃。', 5, 0, 1, 0, '2026-05-06 02:28:34', '2026-05-06 02:28:34'),
  (1900000000000004074, 1900000000000000383, 2099753167800889345, '第一次尝试，味道普通，感觉外卖随便点一个都比这个强。', 3, 2, 1, 0, '2026-05-25 13:11:22', '2026-05-25 13:11:22'),
  (1900000000000004076, 1900000000000000383, 2105667671450075137, '做了两次才摸到火候，第一次略老。', 4, 1, 1, 0, '2026-09-20 21:34:52', '2026-09-20 21:34:52'),
  (1900000000000004078, 1900000000000000383, 2105672958714200066, '上周做的，火候说得很明白，跟着时间走不会老。', 5, 15, 1, 0, '2026-07-20 20:01:45', '2026-07-20 20:01:45'),
  (1900000000000004080, 1900000000000000383, 2099379216679469057, '这个做法把面条的鲜味全留住了。', 5, 18, 1, 0, '2026-09-26 23:43:55', '2026-09-26 23:43:55'),
  (1900000000000004082, 1900000000000000383, 2105682187139399682, '上周做的，这个做法把面条的鲜味全留住了。', 5, 13, 1, 0, '2026-06-06 13:59:08', '2026-06-06 13:59:08'),
  (1900000000000004085, 1900000000000000383, 2105666523875917825, '食材都是冰箱里常备的，不用专门跑超市。', 5, 22, 1, 0, '2026-06-12 12:41:42', '2026-06-12 12:41:42'),
  (1900000000000004087, 1900000000000000383, 2105675867279572993, '挺下饭的，就是有点油，下次我沥一下。', 4, 1, 1, 0, '2026-09-03 19:40:51', '2026-09-03 19:40:51'),
  (1900000000000004089, 1900000000000000383, 2099755610811002881, '做出来的卖相一般，但味道是真的好。', 4, 4, 1, 0, '2026-08-06 20:06:03', '2026-08-06 20:06:03'),
  (1900000000000004091, 1900000000000000383, 2105685510701694978, '照着方子，一人份的量刚好，不会做多做少。', 5, 1, 1, 0, '2026-05-04 11:52:45', '2026-05-04 11:52:45'),
  (1900000000000004093, 1900000000000000383, 2099428434026807297, '第二次做，还可以，主要是我刀工不行，切得不均匀。', 4, 10, 1, 0, '2026-06-26 08:05:10', '2026-06-26 08:05:10'),
  (1900000000000004095, 1900000000000000383, 2100442916133593090, '连着做了两次，第二次明显比第一次顺手。', 5, 9, 1, 0, '2026-07-12 15:45:19', '2026-07-12 15:45:19'),
  (1900000000000004099, 1900000000000000383, 2099383503295885313, '满意，就是这个量我家三口人吃有点不够。', 4, 13, 1, 0, '2026-08-15 14:34:40', '2026-08-15 14:34:40'),
  (1900000000000004101, 1900000000000000383, 2099755611784081409, '今天又做了一次，不难吃，但也没到会推荐给别人的程度。', 3, 1, 1, 0, '2026-06-15 14:32:22', '2026-06-15 14:32:22'),
  (1900000000000004103, 1900000000000000383, 2100121454612893698, '做出来了，卖相比菜谱图差一点，味道没差。', 4, 3, 1, 0, '2026-09-07 09:04:54', '2026-09-07 09:04:54'),
  (1900000000000004108, 1900000000000000383, 2099750963513782274, '照着方子，面条的用量给得刚好，不用自己再摸索，第一次做就很稳。', 5, 25, 1, 0, '2026-08-07 12:43:35', '2026-08-07 12:43:35'),
  (1900000000000004110, 1900000000000000383, 2100406228522950657, '今天又做了一次，孩子平时挑食，这次居然添了半碗饭。', 5, 54, 1, 0, '2026-07-08 17:47:31', '2026-07-08 17:47:31'),
  (1900000000000004112, 1900000000000000383, 2100427162000613377, '第一次尝试，已经加入我的常做清单，隔几天就要做一次。', 5, 1, 1, 0, '2026-05-06 17:30:30', '2026-05-06 17:30:30'),
  (1900000000000004116, 1900000000000000383, 2099437330086760449, '家里人说比外卖强多了，还干净。', 5, 0, 1, 0, '2026-05-31 09:19:53', '2026-05-31 09:19:53'),
  (1900000000000004118, 1900000000000000383, 2105681822776016897, '味道比较寡淡，需要自己大改，不太推荐照搬。', 2, 0, 1, 0, '2026-07-30 15:16:44', '2026-07-30 15:16:44');
INSERT INTO t_dish_comment (id, dish_id, user_id, content, rating, like_count, status, deleted, create_time, update_time) VALUES
  (1900000000000004120, 1900000000000000383, 2099701719658409986, '挺好，就是调料里有一样我家没有，用别的代替了。', 4, 4, 1, 0, '2026-08-25 08:20:00', '2026-08-25 08:20:00'),
  (1900000000000004122, 1900000000000000383, 2105666748212461570, '中规中矩，照着做没失败，但也不会再做第二次。', 3, 1, 1, 0, '2026-07-06 18:42:56', '2026-07-06 18:42:56'),
